import * as THREE from 'three'
import { CONFIG } from './config.js'

const W = CONFIG.world

export function smoothstep(edge0, edge1, x) {
  const t = Math.min(1, Math.max(0, (x - edge0) / (edge1 - edge0)))
  return t * t * (3 - 2 * t)
}

export function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value))
}

function hash2(x, z) {
  const value = Math.sin(x * 127.1 + z * 311.7) * 43758.5453123
  return value - Math.floor(value)
}

export function noise2(x, z) {
  const xi = Math.floor(x)
  const zi = Math.floor(z)
  const xf = x - xi
  const zf = z - zi
  const u = xf * xf * (3 - 2 * xf)
  const v = zf * zf * (3 - 2 * zf)
  const a = hash2(xi, zi)
  const b = hash2(xi + 1, zi)
  const c = hash2(xi, zi + 1)
  const d = hash2(xi + 1, zi + 1)
  return (a + (b - a) * u) * (1 - v) + (c + (d - c) * u) * v
}

function fbm(x, z) {
  let total = 0
  let amplitude = 0.5
  let frequency = 1
  for (let i = 0; i < 4; i += 1) {
    total += noise2(x * frequency, z * frequency) * amplitude
    frequency *= 2.03
    amplitude *= 0.5
  }
  return total
}

export function lakeDepth(x, z) {
  const d = Math.hypot(x - W.lake.x, z - W.lake.z)
  if (d > W.lake.shore) return 0
  const t = 1 - smoothstep(W.lake.radius * 0.42, W.lake.shore, d)
  return -4.1 * Math.pow(Math.max(0, t), 1.3)
}

export function height(x, z) {
  const r = Math.hypot(x, z)
  let h = 1.0 * Math.sin(x * 0.045 + 0.5) * Math.cos(z * 0.05 - 0.8)
  h += 0.55 * Math.sin(x * 0.09 + 1.7) * Math.sin(z * 0.08 + 0.6)
  h += 0.9 * (fbm(x * 0.06, z * 0.06) - 0.5)
  h += Math.pow(smoothstep(68, 128, r), 1.5) * (20 + 11 * fbm(x * 0.017 + 3, z * 0.017 - 2))
  h += lakeDepth(x, z)
  return h
}

export function pathCurve() {
  const points = CONFIG.path.map(([x, z]) => new THREE.Vector3(x, 0, z))
  return new THREE.CatmullRomCurve3(points, true, 'catmullrom', 0.5)
}

const trail = pathCurve().getPoints(420)
export const pathSamples = trail.map(point => [point.x, point.z])

export function pathDistance(x, z) {
  let best = Infinity
  for (let i = 0; i < trail.length; i += 1) {
    const dx = x - trail[i].x
    const dz = z - trail[i].z
    const d = dx * dx + dz * dz
    if (d < best) best = d
  }
  return Math.sqrt(best)
}

export function isUnderwater(x, z) {
  return height(x, z) < W.waterLevel + 0.05
}

export function terrainColor(x, z, h, target) {
  const variation = fbm(x * 0.11 + 12, z * 0.11 - 8)
  const grass = new THREE.Color().setHSL(0.24 + variation * 0.035, 0.42 + variation * 0.14, 0.36 + variation * 0.1)
  const dry = new THREE.Color(0x9cb85c)
  const sand = new THREE.Color(0xdec994)
  const rock = new THREE.Color(0x939088)
  const lakeDist = Math.hypot(x - W.lake.x, z - W.lake.z)

  let color = grass.clone().lerp(dry, smoothstep(0.52, 0.72, variation) * 0.7)

  if (lakeDist < W.lake.shore + 1.5 && h < 0.9) {
    color.lerp(sand, 1 - smoothstep(W.lake.shore * 0.62, W.lake.shore + 1.5, lakeDist))
  }
  if (h > 9) color.lerp(rock, smoothstep(9, 18, h) * 0.9)

  const grad = Math.abs(height(x + 1.4, z) - h) + Math.abs(height(x, z + 1.4) - h)
  if (grad > 1.1) color.lerp(rock, smoothstep(1.1, 2.4, grad) * 0.8)

  if (h < W.waterLevel - 0.15) color.lerp(new THREE.Color(0x5f7d58), 0.5)

  target.copy(color)
}

export function createTerrain(scene) {
  const size = W.size
  const segments = 150
  const geometry = new THREE.PlaneGeometry(size, size, segments, segments)
  geometry.rotateX(-Math.PI / 2)

  const position = geometry.attributes.position
  const colors = new Float32Array(position.count * 3)
  const color = new THREE.Color()
  for (let i = 0; i < position.count; i += 1) {
    const x = position.getX(i)
    const z = position.getZ(i)
    const y = height(x, z)
    position.setY(i, y)
    terrainColor(x, z, y, color)
    colors[i * 3] = color.r
    colors[i * 3 + 1] = color.g
    colors[i * 3 + 2] = color.b
  }
  geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3))
  geometry.computeVertexNormals()

  const material = new THREE.MeshStandardMaterial({
    vertexColors: true,
    roughness: 0.97,
    metalness: 0,
    flatShading: false
  })
  const terrain = new THREE.Mesh(geometry, material)
  terrain.receiveShadow = true
  terrain.castShadow = false
  scene.add(terrain)

  const path = buildPathRibbon(trail)
  scene.add(path)

  return { terrain, path, trail }
}

function buildPathRibbon(points) {
  const width = 3.4
  const positions = []
  const colors = []
  const indices = []
  const centerColor = new THREE.Color(0xd2ab74)
  const edgeColor = new THREE.Color(0xb98c55)
  const rows = points.length

  for (let i = 0; i < rows; i += 1) {
    const point = points[i]
    const next = points[(i + 1) % rows]
    const prev = points[(i - 1 + rows) % rows]
    const tangent = new THREE.Vector3(next.x - prev.x, 0, next.z - prev.z).normalize()
    const side = new THREE.Vector3(-tangent.z, 0, tangent.x)
    for (let c = -1; c <= 1; c += 1) {
      const x = point.x + side.x * width * 0.5 * c
      const z = point.z + side.z * width * 0.5 * c
      const y = height(x, z) + 0.055 + (c === 0 ? 0.012 : 0)
      positions.push(x, y, z)
      const mixed = centerColor.clone().lerp(edgeColor, Math.abs(c))
      const v = noise2(x * 0.7, z * 0.7)
      mixed.offsetHSL(0, 0, (v - 0.5) * 0.07)
      colors.push(mixed.r, mixed.g, mixed.b)
    }
  }
  for (let i = 0; i < rows; i += 1) {
    const current = i * 3
    const next = ((i + 1) % rows) * 3
    for (let c = 0; c < 2; c += 1) {
      indices.push(current + c, next + c, current + c + 1)
      indices.push(current + c + 1, next + c, next + c + 1)
    }
  }
  const geometry = new THREE.BufferGeometry()
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3))
  geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3))
  geometry.setIndex(indices)
  geometry.computeVertexNormals()
  const material = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 1, metalness: 0 })
  const mesh = new THREE.Mesh(geometry, material)
  mesh.receiveShadow = true
  mesh.renderOrder = 1
  return mesh
}

export function createMinimap() {
  const size = 512
  const canvas = document.createElement('canvas')
  canvas.width = size
  canvas.height = size
  const ctx = canvas.getContext('2d')
  const image = ctx.createImageData(size, size)
  const color = new THREE.Color()
  const extent = W.radius + 12
  for (let py = 0; py < size; py += 1) {
    for (let px = 0; px < size; px += 1) {
      const x = (px / size - 0.5) * extent * 2
      const z = (py / size - 0.5) * extent * 2
      const h = height(x, z)
      if (h < W.waterLevel) {
        const depth = smoothstep(W.waterLevel, W.waterLevel - 3, h)
        color.setHSL(0.55, 0.5, 0.48 - depth * 0.16)
      } else {
        terrainColor(x, z, h, color)
        const shade = 0.88 + smoothstep(0, 8, h) * 0.12
        color.multiplyScalar(shade)
      }
      const i = (py * size + px) * 4
      image.data[i] = color.r * 255
      image.data[i + 1] = color.g * 255
      image.data[i + 2] = color.b * 255
      image.data[i + 3] = 255
    }
  }
  ctx.putImageData(image, 0, 0)

  ctx.save()
  ctx.translate(size / 2, size / 2)
  const scale = size / (extent * 2)
  ctx.strokeStyle = 'rgba(196, 148, 88, 0.95)'
  ctx.lineWidth = 5
  ctx.lineCap = 'round'
  ctx.lineJoin = 'round'
  ctx.beginPath()
  trail.forEach((point, index) => {
    const px = point.x * scale
    const pz = point.z * scale
    if (index === 0) ctx.moveTo(px, pz)
    else ctx.lineTo(px, pz)
  })
  ctx.closePath()
  ctx.stroke()
  ctx.restore()

  return canvas
}

import * as THREE from 'three'

const HOOF = 0x4a3728
const SADDLE = 0x8a562b
const BLANKET = 0xc9533f
const EYE = 0x1d1a18

function box(w, h, d, material, x = 0, y = 0, z = 0) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material)
  mesh.position.set(x, y, z)
  mesh.castShadow = true
  mesh.receiveShadow = true
  return mesh
}

function standard(color, roughness = 0.82) {
  return new THREE.MeshStandardMaterial({ color, roughness, metalness: 0 })
}

export function createHorse(coat, mane) {
  const root = new THREE.Group()
  const bodyGroup = new THREE.Group()
  root.add(bodyGroup)

  const coatMat = standard(coat.body, 0.78)
  const shadeMat = standard(coat.shade, 0.82)
  const maneMat = standard(mane, 0.92)
  const hoofMat = standard(HOOF, 0.7)
  const muzzleMat = standard(new THREE.Color(coat.shade).multiplyScalar(0.8), 0.85)
  const eyeMat = standard(EYE, 0.35)
  const saddleMat = standard(SADDLE, 0.72)
  const blanketMat = standard(BLANKET, 0.88)
  const starMat = standard(0xfaf3df, 0.9)

  const body = box(0.9, 0.86, 1.92, coatMat, 0, 1.62, 0)
  bodyGroup.add(body)
  bodyGroup.add(box(0.94, 0.76, 0.62, shadeMat, 0, 1.55, 0.62))
  bodyGroup.add(box(0.96, 0.82, 0.74, coatMat, 0, 1.68, -0.66))

  // Neck + head -------------------------------------------------------------
  const neckGroup = new THREE.Group()
  neckGroup.position.set(0, 1.98, 0.68)
  neckGroup.rotation.x = 0.46
  bodyGroup.add(neckGroup)
  neckGroup.add(box(0.46, 1.08, 0.52, coatMat, 0, 0.52, 0))
  neckGroup.add(box(0.52, 0.5, 0.58, coatMat, 0, 0.1, 0.02))

  const headGroup = new THREE.Group()
  headGroup.position.set(0, 1.06, 0.1)
  headGroup.rotation.x = -0.3
  neckGroup.add(headGroup)
  headGroup.add(box(0.46, 0.46, 0.82, coatMat, 0, 0.08, 0.24))
  headGroup.add(box(0.38, 0.34, 0.3, muzzleMat, 0, -0.04, 0.72))
  headGroup.add(box(0.4, 0.1, 0.12, shadeMat, 0, -0.17, 0.82))
  headGroup.add(box(0.07, 0.07, 0.06, eyeMat, 0.235, 0.12, 0.42))
  headGroup.add(box(0.07, 0.07, 0.06, eyeMat, -0.235, 0.12, 0.42))
  headGroup.add(box(0.28, 0.16, 0.05, starMat, 0, 0.25, 0.62))

  const earL = box(0.13, 0.3, 0.12, coatMat, 0.15, 0.4, 0.02)
  earL.rotation.z = 0.16
  const earR = box(0.13, 0.3, 0.12, coatMat, -0.15, 0.4, 0.02)
  earR.rotation.z = -0.16
  headGroup.add(earL, earR)
  headGroup.add(box(0.1, 0.18, 0.1, shadeMat, 0, 0.36, 0.12))

  // Mane and forelock -------------------------------------------------------
  const maneParts = []
  for (let i = 0; i < 5; i += 1) {
    const piece = box(0.17, 0.32 - i * 0.02, 0.24, maneMat, 0, 0.18 + i * 0.2, -0.31)
    piece.rotation.x = -0.1
    neckGroup.add(piece)
    maneParts.push(piece)
  }
  const forelock = box(0.24, 0.2, 0.18, maneMat, 0, 0.34, 0.16)
  forelock.rotation.x = 0.2
  headGroup.add(forelock)

  // Tail --------------------------------------------------------------------
  const tailGroup = new THREE.Group()
  tailGroup.position.set(0, 1.98, -0.98)
  tailGroup.rotation.x = 0.55
  bodyGroup.add(tailGroup)
  const tailParts = []
  for (let i = 0; i < 4; i += 1) {
    const piece = box(0.2 - i * 0.025, 0.44, 0.22 - i * 0.02, maneMat, 0, -0.18 - i * 0.32, 0)
    piece.rotation.x = -0.16 - i * 0.04
    tailGroup.add(piece)
    tailParts.push(piece)
  }

  // Saddle ------------------------------------------------------------------
  const saddleGroup = new THREE.Group()
  saddleGroup.position.set(0, 2.08, -0.12)
  bodyGroup.add(saddleGroup)
  saddleGroup.add(box(1.16, 0.09, 1.08, blanketMat, 0, 0.02, 0))
  saddleGroup.add(box(0.92, 0.22, 0.82, saddleMat, 0, 0.14, 0))
  saddleGroup.add(box(0.16, 0.2, 0.16, saddleMat, 0, 0.3, 0.34))
  saddleGroup.add(box(0.28, 0.3, 0.13, saddleMat, 0, 0.32, -0.38))
  for (const side of [-1, 1]) {
    saddleGroup.add(box(0.07, 0.56, 0.06, standard(0x5c3a1c, 0.8), side * 0.5, -0.16, -0.06))
    saddleGroup.add(box(0.16, 0.2, 0.12, standard(0xcdb47a, 0.5), side * 0.5, -0.46, -0.06))
  }

  const lucky = new THREE.Group()
  lucky.position.set(0.5, 1.98, -0.3)
  lucky.visible = false
  const horseshoe = new THREE.Mesh(
    new THREE.TorusGeometry(0.11, 0.035, 6, 14, Math.PI),
    new THREE.MeshStandardMaterial({ color: 0xffc63d, emissive: 0xa86a00, emissiveIntensity: 0.5, metalness: 0.6, roughness: 0.3 })
  )
  horseshoe.rotation.z = Math.PI
  lucky.add(horseshoe)
  bodyGroup.add(lucky)

  // Legs --------------------------------------------------------------------
  const legs = []
  const legPositions = [
    { x: 0.31, z: 0.62, phase: 0 },
    { x: -0.31, z: 0.62, phase: Math.PI * 0.94 },
    { x: 0.32, z: -0.68, phase: Math.PI },
    { x: -0.32, z: -0.68, phase: Math.PI * 1.06 }
  ]
  for (const spec of legPositions) {
    const pivot = new THREE.Group()
    pivot.position.set(spec.x, 1.24, spec.z)
    root.add(pivot)
    pivot.add(box(0.32, 0.58, 0.36, coatMat, 0, -0.29, 0))
    const knee = new THREE.Group()
    knee.position.set(0, -0.58, 0)
    pivot.add(knee)
    knee.add(box(0.23, 0.5, 0.26, shadeMat, 0, -0.25, 0))
    knee.add(box(0.28, 0.14, 0.34, hoofMat, 0, -0.57, 0.02))
    legs.push({ pivot, knee, phase: spec.phase, front: spec.z > 0 })
  }

  // Animator ----------------------------------------------------------------
  let gaitPhase = 0
  let clock = 0
  let earTimer = 2 + Math.random() * 3
  let earTwitch = 0

  function animate(dt, state = {}) {
    const speed = state.speed ?? 0
    const grounded = state.grounded !== false
    clock += dt
    const moving = speed > 0.12
    const gait = THREE.MathUtils.clamp(speed / 8.6, 0, 1)
    if (moving) gaitPhase += dt * (3.4 + speed * 1.45)

    const bounce = moving ? Math.sin(gaitPhase * 2) : Math.sin(clock * 1.7)
    bodyGroup.position.y = grounded ? bounce * (moving ? 0.07 * (0.35 + gait) : 0.012) : 0.06
    bodyGroup.rotation.x = (moving && grounded ? Math.cos(gaitPhase * 2) * 0.045 * (0.4 + gait) : 0) + (grounded ? 0 : -0.16)
    bodyGroup.rotation.z = moving ? Math.sin(gaitPhase) * 0.02 * gait : 0

    legs.forEach(leg => {
      if (!grounded) {
        leg.pivot.rotation.x = leg.front ? -0.55 : 0.52
        leg.knee.rotation.x = leg.front ? 0.85 : 0.5
        return
      }
      const swing = moving ? Math.sin(gaitPhase + leg.phase) * (0.22 + gait * 0.62) : 0
      leg.pivot.rotation.x = swing
      leg.knee.rotation.x = moving ? Math.max(0, -Math.sin(gaitPhase + leg.phase)) * (0.2 + gait * 0.85) : 0
    })

    headGroup.rotation.x = -0.3 + (moving ? Math.sin(gaitPhase * 2 + 0.5) * 0.06 * gait : Math.sin(clock * 1.2) * 0.025)
    headGroup.rotation.z = moving ? Math.sin(gaitPhase) * 0.02 : 0
    neckGroup.rotation.x = 0.46 + (moving ? Math.sin(gaitPhase * 2) * 0.035 * gait : 0)

    tailGroup.rotation.z = Math.sin(clock * 2.1 + 0.5) * 0.18 + (moving ? Math.sin(gaitPhase) * 0.12 * gait : 0)
    tailGroup.rotation.x = 0.55 + (moving ? 0.14 * gait + Math.sin(gaitPhase * 2) * 0.05 : Math.sin(clock * 1.4) * 0.04)
    tailParts.forEach((part, index) => {
      part.rotation.z = Math.sin(clock * 2.1 - index * 0.5) * 0.08
    })

    maneParts.forEach((part, index) => {
      part.rotation.x = -0.1 + (moving ? Math.sin(gaitPhase * 2 - index * 0.4) * 0.06 * gait : 0)
    })

    earTimer -= dt
    if (earTimer < 0) {
      earTwitch = 0.4
      earTimer = 3 + Math.random() * 5
    }
    earTwitch = Math.max(0, earTwitch - dt)
    earL.rotation.z = 0.16 + Math.sin(earTwitch * 26) * 0.14
    earR.rotation.z = -0.16 - Math.sin(earTwitch * 22) * 0.1
  }

  function setCoat(nextCoat) {
    coatMat.color.setHex(nextCoat.body)
    shadeMat.color.setHex(nextCoat.shade)
    muzzleMat.color.setHex(new THREE.Color(nextCoat.shade).multiplyScalar(0.8).getHex())
  }

  function setMane(color) {
    maneMat.color.setHex(color)
  }

  function setLucky(value) {
    lucky.visible = value
  }

  return {
    group: root,
    parts: { bodyGroup, neckGroup, headGroup, tailGroup, legs, maneParts },
    animate,
    setCoat,
    setMane,
    setLucky
  }
}

import * as THREE from 'three'
import { CONFIG } from './config.js'
import { height, pathDistance, lakeDepth, createTerrain, createMinimap, noise2, smoothstep, clamp } from './terrain.js'

const W = CONFIG.world

let seed = 20261031
function rand() {
  seed = (seed * 1664525 + 1013904223) >>> 0
  return seed / 4294967296
}
function randRange(min, max) {
  return min + rand() * (max - min)
}
function pick(list) {
  return list[Math.floor(rand() * list.length)]
}

function standard(color, roughness = 0.9) {
  return new THREE.MeshStandardMaterial({ color, roughness, metalness: 0 })
}

function box(w, h, d, material, x = 0, y = 0, z = 0) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material)
  mesh.position.set(x, y, z)
  mesh.castShadow = true
  mesh.receiveShadow = true
  return mesh
}

function cylinder(radiusTop, radiusBottom, h, segments, material, x = 0, y = 0, z = 0) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radiusTop, radiusBottom, h, segments), material)
  mesh.position.set(x, y, z)
  mesh.castShadow = true
  mesh.receiveShadow = true
  return mesh
}

function makeLabelSprite(text, { width = 512, height = 128, background = 'rgba(255, 249, 235, 0.94)', color = '#3c2a1d', fontSize = 58, border = '#5c3a1c', marker = false } = {}) {
  const canvas = document.createElement('canvas')
  canvas.width = width
  canvas.height = height
  const ctx = canvas.getContext('2d')
  const radius = marker ? 30 : 34
  const padding = marker ? 8 : 8
  ctx.fillStyle = background
  ctx.strokeStyle = border
  ctx.lineWidth = marker ? 8 : 6
  ctx.beginPath()
  ctx.roundRect(padding, padding, width - padding * 2, height - padding * 2, radius)
  ctx.fill()
  ctx.stroke()
  ctx.fillStyle = color
  ctx.font = `${marker ? 76 : fontSize}px Fredoka, Nunito, sans-serif`
  ctx.textAlign = 'center'
  ctx.textBaseline = 'middle'
  ctx.fillText(text, width / 2, height / 2 + (marker ? 4 : 2))
  const texture = new THREE.CanvasTexture(canvas)
  texture.colorSpace = THREE.SRGBColorSpace
  texture.anisotropy = 4
  const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: texture, transparent: true, depthWrite: false }))
  const aspect = width / height
  sprite.scale.set(marker ? 1.1 : 3.2, (marker ? 1.1 : 3.2) / aspect, 1)
  return sprite
}

function makeGlowTexture() {
  const canvas = document.createElement('canvas')
  canvas.width = 128
  canvas.height = 128
  const ctx = canvas.getContext('2d')
  const gradient = ctx.createRadialGradient(64, 64, 0, 64, 64, 64)
  gradient.addColorStop(0, 'rgba(255, 231, 135, 0.95)')
  gradient.addColorStop(0.35, 'rgba(255, 207, 82, 0.45)')
  gradient.addColorStop(1, 'rgba(255, 196, 60, 0)')
  ctx.fillStyle = gradient
  ctx.fillRect(0, 0, 128, 128)
  const texture = new THREE.CanvasTexture(canvas)
  texture.colorSpace = THREE.SRGBColorSpace
  return texture
}

export function createWorld(scene) {
  const root = new THREE.Group()
  scene.add(root)

  const colliders = []
  const animated = []
  const glows = []

  scene.fog = new THREE.Fog(0xd9e6cf, 85, 235)
  const terrainData = createTerrain(scene)
  const minimap = createMinimap()

  // Sky ---------------------------------------------------------------------
  const sunDirection = new THREE.Vector3(-0.52, 0.58, 0.38).normalize()
  const skyMaterial = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
    uniforms: {
      topColor: { value: new THREE.Color(0x5aa7dd) },
      horizonColor: { value: new THREE.Color(0xfbe6bd) },
      groundColor: { value: new THREE.Color(0xbfd4a9) },
      sunColor: { value: new THREE.Color(0xfff0c4) },
      sunDirection: { value: sunDirection }
    },
    vertexShader: `
      varying vec3 vWorld;
      void main() {
        vec4 world = modelMatrix * vec4(position, 1.0);
        vWorld = world.xyz;
        gl_Position = projectionMatrix * viewMatrix * world;
      }
    `,
    fragmentShader: `
      uniform vec3 topColor;
      uniform vec3 horizonColor;
      uniform vec3 groundColor;
      uniform vec3 sunColor;
      uniform vec3 sunDirection;
      varying vec3 vWorld;
      void main() {
        vec3 dir = normalize(vWorld);
        float h = dir.y;
        vec3 color = mix(horizonColor, topColor, pow(clamp(h, 0.0, 1.0), 0.62));
        color = mix(groundColor, color, smoothstep(-0.08, 0.14, h));
        float glow = pow(max(dot(dir, sunDirection), 0.0), 26.0);
        float halo = pow(max(dot(dir, sunDirection), 0.0), 5.0);
        color += sunColor * (glow * 0.95 + halo * 0.22);
        gl_FragColor = vec4(color, 1.0);
      }
    `
  })
  const sky = new THREE.Mesh(new THREE.SphereGeometry(520, 32, 18), skyMaterial)
  scene.add(sky)

  const sunSprite = new THREE.Sprite(new THREE.SpriteMaterial({
    map: makeGlowTexture(),
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    opacity: 0.85
  }))
  sunSprite.scale.set(110, 110, 1)
  sunSprite.position.copy(sunDirection).multiplyScalar(390)
  scene.add(sunSprite)

  // Lights ------------------------------------------------------------------
  const hemi = new THREE.HemisphereLight(0xcfe6ff, 0x74884f, 0.85)
  scene.add(hemi)
  const sun = new THREE.DirectionalLight(0xffe2b3, 2.35)
  sun.position.copy(sunDirection).multiplyScalar(120)
  sun.castShadow = true
  sun.shadow.mapSize.set(2048, 2048)
  sun.shadow.camera.left = -85
  sun.shadow.camera.right = 85
  sun.shadow.camera.top = 85
  sun.shadow.camera.bottom = -85
  sun.shadow.camera.near = 10
  sun.shadow.camera.far = 320
  sun.shadow.bias = -0.0005
  sun.shadow.normalBias = 0.035
  sun.target.position.set(0, 0, 0)
  scene.add(sun, sun.target)
  const fill = new THREE.DirectionalLight(0xb9d6ff, 0.35)
  fill.position.set(50, 35, -70)
  scene.add(fill)

  // Clouds ------------------------------------------------------------------
  const cloudMat = new THREE.MeshStandardMaterial({ color: 0xfffdf5, roughness: 1, flatShading: true })
  const cloudGeometry = new THREE.IcosahedronGeometry(1, 1)
  const cloudBlobs = []
  for (let c = 0; c < 8; c += 1) {
    const cloud = new THREE.Group()
    const count = 3 + Math.floor(rand() * 3)
    for (let i = 0; i < count; i += 1) {
      const blob = new THREE.Mesh(cloudGeometry, cloudMat)
      blob.position.set(randRange(-6, 6), randRange(-0.8, 0.8), randRange(-2.5, 2.5))
      blob.scale.set(randRange(2.6, 4.8), randRange(1.2, 2), randRange(2.2, 3.4))
      cloud.add(blob)
    }
    cloud.position.set(randRange(-100, 100), randRange(34, 52), randRange(-100, 100))
    cloud.userData.speed = randRange(0.35, 0.9)
    root.add(cloud)
    cloudBlobs.push(cloud)
  }

  // Birds -------------------------------------------------------------------
  const birdMat = standard(0x3d4038, 0.8)
  const birds = []
  for (let i = 0; i < 7; i += 1) {
    const bird = new THREE.Group()
    const body = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.12, 0.46), birdMat)
    bird.add(body)
    const wings = []
    for (const side of [-1, 1]) {
      const wing = new THREE.Mesh(new THREE.BoxGeometry(0.7, 0.04, 0.22), birdMat)
      wing.position.x = side * 0.36
      wing.geometry.translate(side * 0.35, 0, 0)
      bird.add(wing)
      wings.push({ wing, side })
    }
    bird.userData = {
      radius: randRange(28, 64),
      speed: randRange(0.06, 0.13),
      phase: randRange(0, Math.PI * 2),
      flap: randRange(6, 10),
      height: randRange(16, 30),
      center: new THREE.Vector3(randRange(-25, 25), 0, randRange(-25, 25))
    }
    bird.scale.setScalar(randRange(0.8, 1.3))
    root.add(bird)
    birds.push({ group: bird, wings, ...bird.userData })
  }

  // Water -------------------------------------------------------------------
  const waterUniforms = {
    time: { value: 0 },
    deep: { value: new THREE.Color(0x2f7f9e) },
    shallow: { value: new THREE.Color(0x7ac6c8) },
    sky: { value: new THREE.Color(0xd9ecf2) }
  }
  const waterMaterial = new THREE.ShaderMaterial({
    transparent: true,
    uniforms: waterUniforms,
    vertexShader: `
      uniform float time;
      varying vec3 vWorld;
      varying vec2 vUv;
      void main() {
        vec3 p = position;
        float wave = sin(p.x * 0.55 + time * 1.1) * 0.05 + cos(p.y * 0.7 - time * 0.8) * 0.04;
        p.z += wave;
        vec4 world = modelMatrix * vec4(p, 1.0);
        vWorld = world.xyz;
        vUv = uv;
        gl_Position = projectionMatrix * viewMatrix * world;
      }
    `,
    fragmentShader: `
      uniform float time;
      uniform vec3 deep;
      uniform vec3 shallow;
      uniform vec3 sky;
      varying vec3 vWorld;
      varying vec2 vUv;
      void main() {
        float ripple = sin(vWorld.x * 0.8 + time * 1.5) * sin(vWorld.z * 0.72 - time * 1.1);
        float ripple2 = sin(vWorld.x * 2.1 - time * 1.8) * cos(vWorld.z * 1.7 + time * 1.3);
        float h = ripple * 0.12 + ripple2 * 0.08;
        vec3 color = mix(deep, shallow, smoothstep(-0.2, 0.5, h));
        vec3 viewDir = normalize(cameraPosition - vWorld);
        float fres = pow(1.0 - clamp(viewDir.y, 0.0, 1.0), 2.0);
        color = mix(color, sky, fres * 0.45);
        float sparkle = pow(max(0.0, ripple * ripple2), 6.0) * 0.35;
        color += sparkle;
        float edge = smoothstep(0.46, 0.5, length(vUv - 0.5));
        gl_FragColor = vec4(color, 0.92 - edge * 0.2);
      }
    `
  })
  const water = new THREE.Mesh(new THREE.CircleGeometry(25.5, 72), waterMaterial)
  water.rotation.x = -Math.PI / 2
  water.position.set(W.lake.x, W.waterLevel, W.lake.z)
  water.receiveShadow = false
  root.add(water)

  // Lily pads and reeds -----------------------------------------------------
  const lilyMat = new THREE.MeshStandardMaterial({ color: 0x4c8a4a, roughness: 0.85, side: THREE.DoubleSide })
  const lilyGeometry = new THREE.CircleGeometry(0.55, 7)
  const lilies = new THREE.InstancedMesh(lilyGeometry, lilyMat, 34)
  const dummy = new THREE.Object3D()
  let lilyCount = 0
  for (let i = 0; i < 150 && lilyCount < 34; i += 1) {
    const angle = rand() * Math.PI * 2
    const radius = randRange(3, 17)
    const x = W.lake.x + Math.cos(angle) * radius
    const z = W.lake.z + Math.sin(angle) * radius
    if (height(x, z) > W.waterLevel - 0.35) continue
    dummy.position.set(x, W.waterLevel + 0.05, z)
    dummy.rotation.set(-Math.PI / 2, 0, rand() * Math.PI)
    dummy.scale.setScalar(randRange(0.7, 1.5))
    dummy.updateMatrix()
    lilies.setMatrixAt(lilyCount, dummy.matrix)
    lilyCount += 1
  }
  lilies.count = lilyCount
  root.add(lilies)

  const reedMat = standard(0x6e8a4a, 0.9)
  const reeds = new THREE.InstancedMesh(new THREE.ConeGeometry(0.055, 1.5, 3), reedMat, 170)
  let reedCount = 0
  for (let i = 0; i < 900 && reedCount < 170; i += 1) {
    const angle = rand() * Math.PI * 2
    const radius = randRange(19, 27)
    const x = W.lake.x + Math.cos(angle) * radius
    const z = W.lake.z + Math.sin(angle) * radius
    const h = height(x, z)
    if (h < W.waterLevel - 0.6 || h > W.waterLevel + 0.75) continue
    dummy.position.set(x, h + 0.7, z)
    dummy.rotation.set(randRange(-0.2, 0.2), rand() * Math.PI, randRange(-0.2, 0.2))
    dummy.scale.set(1, randRange(0.7, 1.4), 1)
    dummy.updateMatrix()
    reeds.setMatrixAt(reedCount, dummy.matrix)
    reedCount += 1
  }
  reeds.count = reedCount
  reeds.castShadow = true
  root.add(reeds)

  // Trees -------------------------------------------------------------------
  const treeSpots = []
  function treeAllowed(x, z) {
    if (Math.hypot(x, z) > W.radius - 6) return false
    if (pathDistance(x, z) < 5.2) return false
    if (Math.hypot(x - W.lake.x, z - W.lake.z) < W.lake.shore + 1) return false
    if (Math.hypot(x - W.barn.x, z - W.barn.z) < 16) return false
    if (Math.hypot(x - W.windmill.x, z - W.windmill.z) < 9) return false
    if (Math.hypot(x - W.elderOak.x, z - W.elderOak.z) < 10) return false
    if (Math.abs(x - W.dock.x) < 7 && z > 10 && z < 36) return false
    if (Math.hypot(x - W.spawn.x, z - W.spawn.z) < 12) return false
    for (const spot of treeSpots) {
      if (Math.hypot(x - spot.x, z - spot.z) < 4.2) return false
    }
    return true
  }
  for (let i = 0; i < 1400 && treeSpots.length < 118; i += 1) {
    const x = randRange(-W.radius + 4, W.radius - 4)
    const z = randRange(-W.radius + 4, W.radius - 4)
    if (!treeAllowed(x, z)) continue
    treeSpots.push({ x, z, scale: randRange(0.75, 1.55), pine: rand() > 0.32 })
  }

  const pineSpots = treeSpots.filter(spot => spot.pine)
  const leafSpots = treeSpots.filter(spot => !spot.pine)

  const trunkMat = standard(0x7a5133, 0.95)
  const pineTrunk = new THREE.InstancedMesh(new THREE.CylinderGeometry(0.22, 0.34, 1, 6), trunkMat, pineSpots.length)
  const pineFoliage = new THREE.InstancedMesh(new THREE.ConeGeometry(1, 1, 7), standard(0x4e8246, 0.95), pineSpots.length * 3)
  const pineColors = [0x3f7b46, 0x4c8a4d, 0x5d9753, 0x377045]
  let pineFoliageIndex = 0
  pineSpots.forEach((spot, index) => {
    const ground = height(spot.x, spot.z)
    const s = spot.scale
    dummy.position.set(spot.x, ground + 1.4 * s, spot.z)
    dummy.rotation.set(0, rand() * Math.PI, 0)
    dummy.scale.set(s, 2.8 * s, s)
    dummy.updateMatrix()
    pineTrunk.setMatrixAt(index, dummy.matrix)
    for (let layer = 0; layer < 3; layer += 1) {
      const layerScale = s * (1.55 - layer * 0.28)
      dummy.position.set(spot.x, ground + (2.5 + layer * 1.25) * s, spot.z)
      dummy.rotation.set(0, rand() * Math.PI, 0)
      dummy.scale.set(layerScale, 2.35 * s * (1 - layer * 0.06), layerScale)
      dummy.updateMatrix()
      pineFoliage.setMatrixAt(pineFoliageIndex, dummy.matrix)
      pineFoliage.setColorAt(pineFoliageIndex, new THREE.Color(pick(pineColors)))
      pineFoliageIndex += 1
    }
    colliders.push({ x: spot.x, z: spot.z, r: 0.65 * s })
  })
  pineTrunk.castShadow = pineTrunk.receiveShadow = true
  pineFoliage.castShadow = pineFoliage.receiveShadow = true
  pineFoliage.instanceColor.needsUpdate = true
  root.add(pineTrunk, pineFoliage)

  const leafTrunk = new THREE.InstancedMesh(new THREE.CylinderGeometry(0.26, 0.4, 1, 6), trunkMat, leafSpots.length)
  const leafFoliage = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(1, 1), standard(0x6aa257, 0.95), leafSpots.length * 4)
  const leafColors = [0x6aa257, 0x7cb35e, 0x5b944d, 0x8abf69, 0x568f52]
  let leafFoliageIndex = 0
  leafSpots.forEach((spot, index) => {
    const ground = height(spot.x, spot.z)
    const s = spot.scale
    dummy.position.set(spot.x, ground + 2 * s, spot.z)
    dummy.rotation.set(0, rand() * Math.PI, 0)
    dummy.scale.set(s, 4 * s, s)
    dummy.updateMatrix()
    leafTrunk.setMatrixAt(index, dummy.matrix)
    for (let blob = 0; blob < 4; blob += 1) {
      const angle = (blob / 4) * Math.PI * 2 + rand()
      dummy.position.set(
        spot.x + Math.cos(angle) * 1.5 * s,
        ground + (4.3 + rand() * 1.4) * s,
        spot.z + Math.sin(angle) * 1.5 * s
      )
      dummy.rotation.set(rand() * Math.PI, rand() * Math.PI, 0)
      dummy.scale.set(2.3 * s, 1.9 * s, 2.3 * s)
      dummy.updateMatrix()
      leafFoliage.setMatrixAt(leafFoliageIndex, dummy.matrix)
      leafFoliage.setColorAt(leafFoliageIndex, new THREE.Color(pick(leafColors)))
      leafFoliageIndex += 1
    }
    colliders.push({ x: spot.x, z: spot.z, r: 0.7 * s })
  })
  leafTrunk.castShadow = leafTrunk.receiveShadow = true
  leafFoliage.castShadow = leafFoliage.receiveShadow = true
  leafFoliage.instanceColor.needsUpdate = true
  root.add(leafTrunk, leafFoliage)

  // Grass -------------------------------------------------------------------
  const bladeGeometry = (() => {
    const positions = []
    const indices = []
    for (let i = 0; i < 3; i += 1) {
      const angle = (i / 3) * Math.PI * 2 + 0.4
      const lean = 0.18
      const dx = Math.cos(angle) * 0.09
      const dz = Math.sin(angle) * 0.09
      const tipX = Math.cos(angle) * lean
      const tipZ = Math.sin(angle) * lean
      const base = positions.length / 3
      positions.push(-dx, 0, -dz, dx, 0, dz, tipX, 0.82, tipZ)
      indices.push(base, base + 1, base + 2)
    }
    const geometry = new THREE.BufferGeometry()
    geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3))
    geometry.setIndex(indices)
    geometry.computeVertexNormals()
    return geometry
  })()
  const grassMaterial = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 1, side: THREE.DoubleSide, vertexColors: false })
  const grass = new THREE.InstancedMesh(bladeGeometry, grassMaterial, 3200)
  const grassColors = [0x679b47, 0x77ad50, 0x5c8f42, 0x83b85c, 0x6fa24b]
  let grassCount = 0
  for (let i = 0; i < 9000 && grassCount < 3200; i += 1) {
    const x = randRange(-W.radius + 2, W.radius - 2)
    const z = randRange(-W.radius + 2, W.radius - 2)
    if (height(x, z) < W.waterLevel + 0.15) continue
    if (pathDistance(x, z) < 1.65) continue
    if (Math.hypot(x - W.barn.x, z - W.barn.z) < 9) continue
    if (Math.hypot(x - W.windmill.x, z - W.windmill.z) < 6) continue
    if (Math.hypot(x - W.spawn.x, z - W.spawn.z) < 4) continue
    dummy.position.set(x, height(x, z), z)
    dummy.rotation.set(0, rand() * Math.PI, 0)
    dummy.scale.setScalar(randRange(0.6, 1.5))
    dummy.updateMatrix()
    grass.setMatrixAt(grassCount, dummy.matrix)
    grass.setColorAt(grassCount, new THREE.Color(pick(grassColors)))
    grassCount += 1
  }
  grass.count = grassCount
  grass.instanceColor.needsUpdate = true
  grass.receiveShadow = true
  root.add(grass)

  // Flowers -----------------------------------------------------------------
  const flowerColors = [0xfff4d8, 0xffd166, 0xf78fb3, 0xc8a2ff, 0xff8b6b, 0x9fd8ff]
  const stemMat = standard(0x568b3e, 0.9)
  const stems = new THREE.InstancedMesh(new THREE.CylinderGeometry(0.025, 0.035, 0.5, 3), stemMat, 520)
  const heads = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(0.13, 0), standard(0xffffff, 0.75), 520)
  let flowerCount = 0
  for (let i = 0; i < 3000 && flowerCount < 520; i += 1) {
    const clusterX = randRange(-95, 95)
    const clusterZ = randRange(-95, 95)
    if (height(clusterX, clusterZ) < W.waterLevel + 0.2) continue
    if (pathDistance(clusterX, clusterZ) < 2.2) continue
    if (Math.hypot(clusterX - W.barn.x, clusterZ - W.barn.z) < 10) continue
    if (Math.hypot(clusterX - W.spawn.x, clusterZ - W.spawn.z) < 5) continue
    for (let f = 0; f < 3 && flowerCount < 520; f += 1) {
      const x = clusterX + randRange(-2.2, 2.2)
      const z = clusterZ + randRange(-2.2, 2.2)
      if (height(x, z) < W.waterLevel + 0.2 || pathDistance(x, z) < 1.9) continue
      const ground = height(x, z)
      dummy.position.set(x, ground + 0.25, z)
      dummy.rotation.set(randRange(-0.1, 0.1), rand() * Math.PI, randRange(-0.1, 0.1))
      dummy.scale.setScalar(randRange(0.8, 1.4))
      dummy.updateMatrix()
      stems.setMatrixAt(flowerCount, dummy.matrix)
      dummy.position.set(x, ground + 0.52, z)
      dummy.rotation.set(0, rand() * Math.PI, 0)
      dummy.scale.setScalar(randRange(0.8, 1.5))
      dummy.updateMatrix()
      heads.setMatrixAt(flowerCount, dummy.matrix)
      heads.setColorAt(flowerCount, new THREE.Color(pick(flowerColors)))
      flowerCount += 1
    }
  }
  stems.count = flowerCount
  heads.count = flowerCount
  heads.instanceColor.needsUpdate = true
  stems.castShadow = true
  heads.castShadow = true
  root.add(stems, heads)

  // Rocks -------------------------------------------------------------------
  const rockMat = standard(0x9a968b, 0.95)
  const rocks = new THREE.InstancedMesh(new THREE.DodecahedronGeometry(1, 0), rockMat, 70)
  const rockColors = [0x9a968b, 0x8b877d, 0xa8a496, 0x817d74]
  let rockCount = 0
  for (let i = 0; i < 500 && rockCount < 70; i += 1) {
    const x = randRange(-W.radius + 3, W.radius - 3)
    const z = randRange(-W.radius + 3, W.radius - 3)
    if (pathDistance(x, z) < 4.5) continue
    if (height(x, z) < W.waterLevel + 0.2) continue
    if (Math.hypot(x - W.barn.x, z - W.barn.z) < 13) continue
    if (Math.hypot(x - W.windmill.x, z - W.windmill.z) < 8) continue
    if (Math.hypot(x - W.elderOak.x, z - W.elderOak.z) < 6) continue
    if (Math.hypot(x - W.spawn.x, z - W.spawn.z) < 8) continue
    const s = randRange(0.35, 1.75)
    dummy.position.set(x, height(x, z) + s * 0.35, z)
    dummy.rotation.set(rand() * Math.PI, rand() * Math.PI, rand() * Math.PI)
    dummy.scale.set(s * randRange(0.8, 1.4), s * randRange(0.6, 1), s * randRange(0.8, 1.4))
    dummy.updateMatrix()
    rocks.setMatrixAt(rockCount, dummy.matrix)
    rocks.setColorAt(rockCount, new THREE.Color(pick(rockColors)))
    if (s > 1.05) colliders.push({ x, z, r: s * 0.9 })
    rockCount += 1
  }
  rocks.count = rockCount
  rocks.instanceColor.needsUpdate = true
  rocks.castShadow = rocks.receiveShadow = true
  root.add(rocks)

  // Barn --------------------------------------------------------------------
  const barnGroup = new THREE.Group()
  const barnGround = height(W.barn.x, W.barn.z)
  barnGroup.position.set(W.barn.x, barnGround - 0.35, W.barn.z)
  barnGroup.rotation.y = W.barn.rotation
  root.add(barnGroup)
  const barnRed = standard(0xc44b3b, 0.9)
  const barnWhite = standard(0xf3ead5, 0.85)
  const barnDark = standard(0x51301f, 0.9)
  const roofMat = standard(0x8a4c3b, 0.92)
  const stoneMat = standard(0xaca79a, 0.95)

  barnGroup.add(box(12.4, 0.7, 10.4, stoneMat, 0, 0.35, 0))
  barnGroup.add(box(12, 6.2, 10, barnRed, 0, 3.7, 0))
  barnGroup.add(box(12.6, 0.45, 10.6, barnWhite, 0, 6.85, 0))
  for (const side of [-1, 1]) {
    const roof = box(7.1, 0.45, 11.2, roofMat, side * 2.85, 8.5, 0)
    roof.rotation.z = side * -0.62
    barnGroup.add(roof)
    const trim = box(7.2, 0.16, 0.32, barnWhite, side * 2.85, 8.55, 5.45)
    trim.rotation.z = side * -0.62
    barnGroup.add(trim)
    barnGroup.add(box(0.36, 6.2, 0.4, barnWhite, side * 5.92, 3.7, 4.95))
    barnGroup.add(box(0.36, 6.2, 0.4, barnWhite, side * 5.92, 3.7, -4.95))
  }
  barnGroup.add(box(0.4, 6.2, 0.4, barnWhite, 5.95, 3.7, 0))
  barnGroup.add(box(0.4, 6.2, 0.4, barnWhite, -5.95, 3.7, 0))

  const doorGroup = new THREE.Group()
  doorGroup.position.set(0, 0, 5.06)
  barnGroup.add(doorGroup)
  doorGroup.add(box(3.9, 4.8, 0.2, barnDark, 0, 3.05, 0))
  for (const side of [-1, 1]) {
    const brace = box(0.18, 5.1, 0.1, barnWhite, 0, 3.05, 0.08)
    brace.rotation.z = side * 0.72
    doorGroup.add(brace)
  }
  doorGroup.add(box(4.4, 0.24, 0.3, barnWhite, 0, 5.55, 0.1))
  doorGroup.add(box(0.24, 4.9, 0.3, barnWhite, -1.95, 3.05, 0.1))
  doorGroup.add(box(0.24, 4.9, 0.3, barnWhite, 1.95, 3.05, 0.1))
  doorGroup.add(box(0.2, 0.2, 0.2, standard(0xe4b84a, 0.4), 1.5, 3.0, 0.2))

  const loft = box(2.4, 2.2, 0.24, barnDark, 0, 7.2, 5.08)
  barnGroup.add(loft)
  barnGroup.add(box(2.8, 2.6, 0.16, barnWhite, 0, 7.2, 5.02))
  barnGroup.add(box(2.2, 2, 0.26, barnDark, 0, 7.2, 4.95))
  for (const side of [-1, 1]) {
    const window = box(1.4, 1.6, 0.2, barnDark, side * 3.7, 3.9, 5.06)
    barnGroup.add(window)
    barnGroup.add(box(1.7, 0.18, 0.26, barnWhite, side * 3.7, 4.75, 5.08))
    barnGroup.add(box(1.7, 0.18, 0.26, barnWhite, side * 3.7, 3.05, 5.08))
    barnGroup.add(box(0.18, 1.8, 0.26, barnWhite, side * 3.0, 3.9, 5.08))
    barnGroup.add(box(0.18, 1.8, 0.26, barnWhite, side * 4.4, 3.9, 5.08))
  }
  // side windows
  for (const side of [-1, 1]) {
    for (const zPos of [-2.6, 2.6]) {
      barnGroup.add(box(0.2, 1.5, 1.3, barnDark, side * 6.02, 4.1, zPos))
      barnGroup.add(box(0.24, 0.16, 1.5, barnWhite, side * 6.04, 4.9, zPos))
      barnGroup.add(box(0.24, 0.16, 1.5, barnWhite, side * 6.04, 3.3, zPos))
    }
  }
  // Weather vane
  barnGroup.add(box(0.1, 1.4, 0.1, standard(0x44413a, 0.6), 0, 10.2, 0))
  barnGroup.add(box(1.1, 0.08, 0.08, standard(0x44413a, 0.6), 0.25, 10.8, 0))
  const vaneArrow = new THREE.Mesh(new THREE.ConeGeometry(0.22, 0.5, 4), standard(0xc8a044, 0.4))
  vaneArrow.rotation.z = -Math.PI / 2
  vaneArrow.position.set(0.85, 10.8, 0)
  barnGroup.add(vaneArrow)
  colliders.push({ x: W.barn.x, z: W.barn.z, r: 8.4 })

  // Silo
  const siloGroup = new THREE.Group()
  const siloX = W.barn.x + 7.6
  const siloZ = W.barn.z + 2
  siloGroup.position.set(siloX, height(siloX, siloZ) - 0.3, siloZ)
  root.add(siloGroup)
  siloGroup.add(cylinder(2.2, 2.4, 12, 16, standard(0xd8d2c1, 0.9), 0, 6, 0))
  siloGroup.add(cylinder(2.45, 2.45, 0.35, 16, standard(0x9d998c, 0.9), 0, 12.15, 0))
  const dome = new THREE.Mesh(new THREE.SphereGeometry(2.35, 16, 8, 0, Math.PI * 2, 0, Math.PI / 2), standard(0xb7b0a0, 0.9))
  dome.position.y = 12.3
  dome.castShadow = true
  siloGroup.add(dome)
  for (const bandY of [2.6, 6.4, 10.2]) {
    siloGroup.add(cylinder(2.32, 2.32, 0.14, 16, standard(0x9d998c, 0.85), 0, bandY, 0))
  }
  siloGroup.add(box(1.3, 2.5, 0.2, standard(0x7b5f40, 0.9), 0, 1.35, -2.35))
  colliders.push({ x: siloX, z: siloZ, r: 2.8 })

  // Paddock ----------------------------------------------------------------
  const paddock = W.paddock
  const postMat = standard(0x8b6340, 0.9)
  const railMat = standard(0xa87c50, 0.9)
  const posts = []
  const rails = []
  const halfW = paddock.width / 2
  const halfD = paddock.depth / 2
  for (let x = -halfW; x <= halfW + 0.01; x += 2.4) {
    posts.push([x, -halfD])
    posts.push([x, halfD])
  }
  for (let z = -halfD + 2.4; z <= halfD - 2.39; z += 2.4) {
    posts.push([-halfW, z])
    if (z < -2 || z > 1.5) posts.push([halfW, z])
  }
  const postMesh = new THREE.InstancedMesh(new THREE.BoxGeometry(0.22, 1.35, 0.22), postMat, posts.length)
  posts.forEach(([lx, lz], index) => {
    const x = paddock.x + lx
    const z = paddock.z + lz
    dummy.position.set(x, height(x, z) + 0.6, z)
    dummy.rotation.set(0, 0, randRange(-0.03, 0.03))
    dummy.scale.set(1, 1, 1)
    dummy.updateMatrix()
    postMesh.setMatrixAt(index, dummy.matrix)
  })
  postMesh.castShadow = postMesh.receiveShadow = true
  root.add(postMesh)

  const railPairs = []
  for (let i = 0; i < posts.length - 1; i += 1) {
    const a = posts[i]
    const b = posts[i + 1]
    const dist = Math.hypot(b[0] - a[0], b[1] - a[1])
    if (Math.abs(dist - 2.4) > 0.2) continue
    railPairs.push([a, b])
  }
  const railMesh = new THREE.InstancedMesh(new THREE.BoxGeometry(2.55, 0.14, 0.12), railMat, railPairs.length * 2)
  let railIndex = 0
  railPairs.forEach(([a, b]) => {
    const ax = paddock.x + a[0]
    const az = paddock.z + a[1]
    const bx = paddock.x + b[0]
    const bz = paddock.z + b[1]
    const y = (height(ax, az) + height(bx, bz)) / 2
    const angle = Math.atan2(bz - az, bx - ax)
    for (const railY of [0.45, 0.95]) {
      dummy.position.set((ax + bx) / 2, y + railY, (az + bz) / 2)
      dummy.rotation.set(0, -angle, 0)
      dummy.scale.set(1, 1, 1)
      dummy.updateMatrix()
      railMesh.setMatrixAt(railIndex, dummy.matrix)
      railIndex += 1
    }
  })
  railMesh.castShadow = railMesh.receiveShadow = true
  root.add(railMesh)

  // Hay bales
  const hayMat = standard(0xd9b45f, 0.95)
  const hayBand = standard(0xc39a44, 0.9)
  for (const [hx, hz, rot] of [[24.5, 4, 0.2], [27.5, 5.2, -0.4], [26, 2.2, 0.5]]) {
    const hay = new THREE.Group()
    hay.position.set(hx, height(hx, hz) + 0.55, hz)
    hay.rotation.y = rot
    hay.add(new THREE.Mesh(new THREE.BoxGeometry(2.1, 1.1, 1.15), hayMat))
    hay.add(box(2.15, 0.1, 1.2, hayBand, 0, 0.25, 0))
    hay.add(box(2.15, 0.1, 1.2, hayBand, 0, -0.25, 0))
    hay.traverse(child => { if (child.isMesh) { child.castShadow = true; child.receiveShadow = true } })
    root.add(hay)
    colliders.push({ x: hx, z: hz, r: 1.4 })
  }

  // Elder oak ---------------------------------------------------------------
  const oakGroup = new THREE.Group()
  const oakGround = height(W.elderOak.x, W.elderOak.z)
  oakGroup.position.set(W.elderOak.x, oakGround, W.elderOak.z)
  root.add(oakGroup)
  const oakTrunk = cylinder(1.2, 1.75, 7.4, 9, standard(0x6e4a2e, 0.95), 0, 3.7, 0)
  oakTrunk.rotation.z = 0.04
  oakGroup.add(oakTrunk)
  const oakLeafMat = standard(0x477f3f, 0.95)
  const oakBlobs = [
    [0, 9.2, 0, 4.6, 2.6, 4.2],
    [3.4, 8.2, 1.4, 3.1, 2.1, 2.9],
    [-3.2, 8.4, -1.2, 3.4, 2.2, 3.2],
    [1.2, 10.6, -2.2, 3.0, 2.0, 2.8],
    [-1.4, 9.8, 2.6, 2.6, 1.8, 2.5],
    [4.2, 9.6, -1.8, 2.2, 1.7, 2.2]
  ]
  oakBlobs.forEach(([x, y, z, sx, sy, sz]) => {
    const blob = new THREE.Mesh(new THREE.IcosahedronGeometry(1, 1), oakLeafMat)
    blob.position.set(x, y, z)
    blob.scale.set(sx, sy, sz)
    blob.castShadow = true
    blob.receiveShadow = true
    oakGroup.add(blob)
  })
  // Rope swing
  const ropeMat = standard(0xcdb98d, 0.9)
  oakGroup.add(box(0.06, 3.6, 0.06, ropeMat, 2.2, 6.2, 0.4))
  oakGroup.add(box(0.06, 3.6, 0.06, ropeMat, 3.4, 6.2, 0.4))
  oakGroup.add(box(1.5, 0.12, 0.5, standard(0x9a6b3f, 0.9), 2.8, 4.35, 0.4))
  colliders.push({ x: W.elderOak.x, z: W.elderOak.z, r: 2.2 })

  // Dock -------------------------------------------------------------------
  const dockGroup = new THREE.Group()
  dockGroup.position.set(W.dock.x, W.waterLevel, 0)
  root.add(dockGroup)
  const plankMat = standard(0xa87a4a, 0.9)
  const dockPostMat = standard(0x76512f, 0.95)
  const dockZ0 = W.dock.zStart
  const dockZ1 = W.dock.zEnd
  for (let z = dockZ0; z <= dockZ1; z += 0.62) {
    const plank = box(3.4, 0.16, 0.5, plankMat, 0, 0.62, z)
    dockGroup.add(plank)
  }
  for (const side of [-1, 1]) {
    for (let z = dockZ0 - 0.4; z <= dockZ1 + 0.4; z += 3.5) {
      const post = cylinder(0.14, 0.16, 3.6, 6, dockPostMat, side * 1.62, -0.9, z)
      dockGroup.add(post)
      dockGroup.add(cylinder(0.19, 0.19, 0.12, 6, dockPostMat, side * 1.62, 0.74, z))
    }
  }
  const dockSign = makeLabelSprite('LAKESIDE DOCK', { width: 640, height: 110, fontSize: 50 })
  dockSign.position.set(W.dock.x, 5.6, 17.5)
  root.add(dockSign)
  dockSign.userData.baseY = 5.6
  dockSign.userData.bob = 0.02
  glows.push(dockSign)

  // Windmill ---------------------------------------------------------------
  const windmillGroup = new THREE.Group()
  const windGround = height(W.windmill.x, W.windmill.z)
  windmillGroup.position.set(W.windmill.x, windGround - 0.25, W.windmill.z)
  root.add(windmillGroup)
  const windStone = standard(0xd7cdb8, 0.95)
  const windTrim = standard(0x8c6743, 0.9)
  windmillGroup.add(cylinder(2.3, 3.5, 10, 12, windStone, 0, 5, 0))
  windmillGroup.add(cylinder(2.55, 2.55, 0.4, 12, windTrim, 0, 10, 0))
  const windCap = new THREE.Mesh(new THREE.ConeGeometry(2.75, 2.2, 12), standard(0x7e4a36, 0.9))
  windCap.position.y = 11.2
  windCap.castShadow = true
  windmillGroup.add(windCap)
  windmillGroup.add(box(1.3, 2.6, 0.2, standard(0x6b4a2f, 0.9), 0, 1.35, 3.35))
  windmillGroup.add(box(0.9, 0.9, 0.2, standard(0x4f3824, 0.9), 0, 6.8, 2.55))
  windmillGroup.add(box(1.2, 0.16, 0.3, windTrim, 0, 8.1, 2.5))

  const blades = new THREE.Group()
  blades.position.set(0, 8.4, 3.6)
  windmillGroup.add(blades)
  const bladeMat = standard(0xf1e5cd, 0.9)
  const bladeFrame = standard(0x8c6743, 0.9)
  for (let i = 0; i < 4; i += 1) {
    const arm = new THREE.Group()
    arm.rotation.z = (i / 4) * Math.PI * 2
    arm.add(box(0.24, 5.6, 0.18, bladeFrame, 0, 2.8, 0))
    for (let rung = 0; rung < 5; rung += 1) {
      arm.add(box(1.7, 0.12, 0.14, bladeFrame, 0, 1 + rung * 0.95, 0))
    }
    const sail = box(1.45, 4.2, 0.06, bladeMat, 0.55, 2.6, 0.05)
    arm.add(sail)
    blades.add(arm)
  }
  const hub = new THREE.Mesh(new THREE.CylinderGeometry(0.45, 0.45, 0.5, 10), bladeFrame)
  hub.rotation.x = Math.PI / 2
  hub.position.z = 0.1
  blades.add(hub)
  colliders.push({ x: W.windmill.x, z: W.windmill.z, r: 4.1 })

  // Welcome sign -----------------------------------------------------------
  const signGroup = new THREE.Group()
  const signX = 22
  const signZ = -13
  signGroup.position.set(signX, height(signX, signZ), signZ)
  signGroup.rotation.y = 0.3
  root.add(signGroup)
  signGroup.add(box(0.22, 2.9, 0.22, standard(0x7a5331, 0.95), -1.5, 1.45, 0))
  signGroup.add(box(0.22, 2.9, 0.22, standard(0x7a5331, 0.95), 1.5, 1.45, 0))
  signGroup.add(box(4.3, 1.6, 0.2, standard(0xa97745, 0.95), 0, 2.5, 0))
  const signFace = makeLabelSprite('HORSE VALLEY', { width: 760, height: 190, fontSize: 96, background: 'rgba(168, 119, 69, 0)', border: 'rgba(0,0,0,0)' })
  signFace.material.map.needsUpdate = true
  signFace.scale.set(4, 1, 1)
  signFace.position.set(0, 2.5, 0.16)
  signGroup.add(signFace)

  // Apples -----------------------------------------------------------------
  const appleGlowTexture = makeGlowTexture()
  const goldMat = new THREE.MeshStandardMaterial({
    color: 0xffc23c,
    emissive: 0xa66a00,
    emissiveIntensity: 0.35,
    metalness: 0.55,
    roughness: 0.22
  })
  const leafMat = standard(0x5c9c48, 0.8)
  const stemMatApple = standard(0x6b4423, 0.9)
  const ringMat = new THREE.MeshBasicMaterial({ color: 0xffd76a, transparent: true, opacity: 0.55, side: THREE.DoubleSide, depthWrite: false })

  const apples = []
  CONFIG.apples.forEach((spot, index) => {
    const group = new THREE.Group()
    const ground = spot.y !== undefined ? spot.y : height(spot.x, spot.z) + 1.15
    group.position.set(spot.x, ground, spot.z)
    const apple = new THREE.Mesh(new THREE.IcosahedronGeometry(0.34, 1), goldMat)
    apple.scale.y = 0.92
    apple.castShadow = true
    group.add(apple)
    group.add(cylinder(0.035, 0.045, 0.28, 4, stemMatApple, 0, 0.32, 0))
    const leaf = box(0.22, 0.05, 0.13, leafMat, 0.12, 0.42, 0.03)
    leaf.rotation.z = 0.4
    group.add(leaf)
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({ map: appleGlowTexture, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, opacity: 0.85 }))
    glow.scale.set(2.3, 2.3, 1)
    group.add(glow)
    const ring = new THREE.Mesh(new THREE.RingGeometry(0.5, 0.72, 24), ringMat.clone())
    ring.rotation.x = -Math.PI / 2
    ring.position.set(spot.x, (W.waterLevel + 0.07) + (spot.y !== undefined ? 0 : 0), spot.z)
    if (spot.y === undefined) ring.position.y = height(spot.x, spot.z) + 0.07
    root.add(ring)
    root.add(group)
    const appleData = {
      group,
      ring,
      glow,
      apple,
      baseY: ground,
      collected: false,
      label: spot.label,
      index
    }
    ring.visible = false
    apples.push(appleData)
    glows.push(group)
  })

  // NPCs -------------------------------------------------------------------
  function createNpc(definition, key) {
    const group = new THREE.Group()
    const colors = definition.colors
    const skin = standard(colors.skin, 0.85)
    const shirt = standard(colors.shirt, 0.9)
    const pants = standard(colors.pants, 0.9)
    const hair = standard(colors.hair, 0.9)
    const hatMat = standard(colors.hat, 0.85)
    const accent = standard(colors.accent, 0.85)
    const dark = standard(0x33251b, 0.8)

    group.add(box(0.4, 0.9, 0.4, pants, 0.28, 0.45, 0))
    group.add(box(0.4, 0.9, 0.4, pants, -0.28, 0.45, 0))
    group.add(box(0.34, 0.2, 0.52, dark, 0.28, 0.08, 0.07))
    group.add(box(0.34, 0.2, 0.52, dark, -0.28, 0.08, 0.07))
    group.add(box(1.05, 1.15, 0.58, shirt, 0, 1.45, 0))
    const armL = new THREE.Group()
    armL.position.set(0.68, 1.9, 0)
    armL.add(box(0.3, 0.95, 0.34, skin, 0, -0.42, 0))
    group.add(armL)
    const armR = new THREE.Group()
    armR.position.set(-0.68, 1.9, 0)
    armR.add(box(0.3, 0.95, 0.34, skin, 0, -0.42, 0))
    group.add(armR)
    group.add(box(0.64, 0.64, 0.64, skin, 0, 2.36, 0))
    group.add(box(0.66, 0.2, 0.68, hair, 0, 2.6, -0.06))
    group.add(box(0.12, 0.12, 0.06, dark, 0.17, 2.4, 0.33))
    group.add(box(0.12, 0.12, 0.06, dark, -0.17, 2.4, 0.33))
    group.add(box(0.2, 0.18, 0.2, standard(0x6b3f2b, 0.85), 0, 2.27, 0.34))

    if (definition.hat === 'straw') {
      group.add(cylinder(0.78, 0.82, 0.09, 12, hatMat, 0, 2.82, 0))
      group.add(cylinder(0.42, 0.5, 0.42, 12, hatMat, 0, 2.98, 0))
      group.add(cylinder(0.51, 0.51, 0.08, 12, accent, 0, 2.87, 0))
      group.add(box(0.46, 0.5, 0.08, accent, 0, 1.25, 0.31))
      group.add(box(0.16, 0.5, 0.08, accent, 0.4, 1.75, 0.3))
      group.add(box(0.16, 0.5, 0.08, accent, -0.4, 1.75, 0.3))
    } else {
      group.add(cylinder(0.48, 0.5, 0.4, 12, hatMat, 0, 2.88, 0))
      group.add(box(0.8, 0.1, 0.55, hatMat, 0, 2.7, 0.32))
      group.add(box(0.55, 0.5, 0.2, accent, 0, 2.5, 0.36))
      group.add(box(0.72, 0.9, 0.3, standard(0x5f7a46, 0.9), 0, 1.55, -0.43))
    }

    group.traverse(child => { if (child.isMesh) { child.castShadow = true; child.receiveShadow = true } })
    const ground = height(definition.x, definition.z)
    group.position.set(definition.x, ground, definition.z)
    group.rotation.y = Math.atan2(W.spawn.x - definition.x, W.spawn.z - definition.z)
    root.add(group)

    const label = makeLabelSprite(definition.name, { width: 512, height: 108, fontSize: 52 })
    label.position.set(definition.x, ground + 3.55, definition.z)
    root.add(label)
    const marker = makeLabelSprite('!', { width: 128, height: 128, marker: true, background: 'rgba(255, 200, 61, 0.97)', border: '#7a4a16', color: '#6b3d10' })
    marker.position.set(definition.x, ground + 4.35, definition.z)
    root.add(marker)

    return {
      key,
      name: definition.name,
      role: definition.role,
      x: definition.x,
      z: definition.z,
      group,
      armL,
      armR,
      label,
      marker,
      baseGround: ground,
      phase: rand() * Math.PI * 2
    }
  }

  const npcs = Object.entries(CONFIG.npcs).map(([key, definition]) => createNpc(definition, key))

  // Butterflies ------------------------------------------------------------
  const butterflies = []
  const butterflyColors = [0xffd166, 0xf78fb3, 0x9fd8ff, 0xfff4d8]
  for (let i = 0; i < 14; i += 1) {
    const group = new THREE.Group()
    const wingMat = new THREE.MeshBasicMaterial({ color: pick(butterflyColors), side: THREE.DoubleSide })
    const wings = []
    for (const side of [-1, 1]) {
      const wing = new THREE.Mesh(new THREE.PlaneGeometry(0.28, 0.2), wingMat)
      wing.position.x = side * 0.13
      wing.rotation.y = side * 0.2
      group.add(wing)
      wings.push({ wing, side })
    }
    const centerX = randRange(-70, 70)
    const centerZ = randRange(-70, 70)
    group.userData = { centerX, centerZ, phase: rand() * 10, radius: randRange(2, 7), speed: randRange(0.4, 1.1) }
    group.position.set(centerX, height(centerX, centerZ) + 1.3, centerZ)
    root.add(group)
    butterflies.push({ group, wings })
  }

  // Dust / sparkle particles ------------------------------------------------
  const particleCount = 260
  const particlePositions = new Float32Array(particleCount * 3)
  const particleColors = new Float32Array(particleCount * 3)
  const particleSizes = new Float32Array(particleCount)
  const particleAlphas = new Float32Array(particleCount)
  const particleLife = new Float32Array(particleCount)
  const particleMaxLife = new Float32Array(particleCount)
  const particleVelocity = new Float32Array(particleCount * 3)
  const particleGravity = new Float32Array(particleCount)
  const particleGeometry = new THREE.BufferGeometry()
  particleGeometry.setAttribute('position', new THREE.BufferAttribute(particlePositions, 3))
  particleGeometry.setAttribute('color', new THREE.BufferAttribute(particleColors, 3))
  particleGeometry.setAttribute('aSize', new THREE.BufferAttribute(particleSizes, 1))
  particleGeometry.setAttribute('aAlpha', new THREE.BufferAttribute(particleAlphas, 1))
  const particleMaterial = new THREE.ShaderMaterial({
    transparent: true,
    depthWrite: false,
    vertexShader: `
      attribute float aSize;
      attribute float aAlpha;
      varying vec3 vColor;
      varying float vAlpha;
      void main() {
        vColor = color;
        vAlpha = aAlpha;
        vec4 mv = modelViewMatrix * vec4(position, 1.0);
        gl_PointSize = aSize * (240.0 / -mv.z);
        gl_Position = projectionMatrix * mv;
      }
    `,
    fragmentShader: `
      varying vec3 vColor;
      varying float vAlpha;
      void main() {
        float d = length(gl_PointCoord - vec2(0.5));
        float alpha = smoothstep(0.5, 0.12, d) * vAlpha;
        if (alpha < 0.01) discard;
        gl_FragColor = vec4(vColor, alpha);
      }
    `,
    vertexColors: true
  })
  const particles = new THREE.Points(particleGeometry, particleMaterial)
  particles.frustumCulled = false
  scene.add(particles)
  let particleCursor = 0

  function spawnParticles(position, color, count = 8, options = {}) {
    const { spread = 0.48, up = 2.2, size = 9, life = 0.7, gravity = 5.5 } = options
    const c = new THREE.Color(color)
    for (let i = 0; i < count; i += 1) {
      const index = particleCursor
      particleCursor = (particleCursor + 1) % particleCount
      particlePositions[index * 3] = position.x + randRange(-0.2, 0.2)
      particlePositions[index * 3 + 1] = position.y + randRange(-0.05, 0.2)
      particlePositions[index * 3 + 2] = position.z + randRange(-0.2, 0.2)
      particleVelocity[index * 3] = randRange(-spread, spread)
      particleVelocity[index * 3 + 1] = randRange(up * 0.4, up)
      particleVelocity[index * 3 + 2] = randRange(-spread, spread)
      particleColors[index * 3] = c.r
      particleColors[index * 3 + 1] = c.g
      particleColors[index * 3 + 2] = c.b
      particleSizes[index] = size * randRange(0.6, 1.35)
      particleAlphas[index] = 1
      particleLife[index] = life * randRange(0.7, 1.2)
      particleMaxLife[index] = particleLife[index]
      particleGravity[index] = gravity
    }
    particleGeometry.attributes.position.needsUpdate = true
    particleGeometry.attributes.color.needsUpdate = true
    particleGeometry.attributes.aSize.needsUpdate = true
    particleGeometry.attributes.aAlpha.needsUpdate = true
  }

  // Update loops ------------------------------------------------------------
  let elapsed = 0

  function update(dt, time) {
    elapsed = time
    waterUniforms.time.value = time
    blades.rotation.z = time * 0.55

    cloudBlobs.forEach(cloud => {
      cloud.position.x += cloud.userData.speed * dt
      if (cloud.position.x > 120) cloud.position.x = -120
    })

    birds.forEach(bird => {
      const data = bird.group.userData
      const angle = time * data.speed + data.phase
      bird.group.position.set(
        data.center.x + Math.cos(angle) * data.radius,
        data.height + Math.sin(time * 0.8 + data.phase) * 1.2,
        data.center.z + Math.sin(angle) * data.radius
      )
      bird.group.rotation.y = -angle + Math.PI / 2
      const flap = Math.sin(time * data.flap + data.phase) * 0.6
      bird.wings.forEach(({ wing, side }) => {
        wing.rotation.z = side * flap
      })
    })

    apples.forEach(apple => {
      if (apple.collected) return
      apple.group.position.y = apple.baseY + Math.sin(time * 1.8 + apple.index) * 0.14
      apple.group.rotation.y = time * 0.9 + apple.index
      apple.glow.material.opacity = 0.65 + Math.sin(time * 3 + apple.index) * 0.2
    })

    npcs.forEach(npc => {
      npc.group.position.y = npc.baseGround + Math.sin(time * 1.5 + npc.phase) * 0.015
      npc.marker.position.y = npc.baseGround + 4.35 + Math.sin(time * 2.2 + npc.phase) * 0.12
      npc.marker.material.rotation = Math.sin(time * 1.2 + npc.phase) * 0.05
      npc.armR.rotation.z = Math.sin(time * 0.9 + npc.phase) * 0.06
      npc.armL.rotation.z = -Math.sin(time * 0.9 + npc.phase) * 0.06
    })

    butterflies.forEach((butterfly, index) => {
      const data = butterfly.group.userData
      const angle = time * data.speed + data.phase
      const x = data.centerX + Math.cos(angle) * data.radius
      const z = data.centerZ + Math.sin(angle * 0.8) * data.radius
      butterfly.group.position.set(x, height(x, z) + 1.2 + Math.sin(time * 2 + data.phase) * 0.4, z)
      butterfly.group.rotation.y = -angle
      butterfly.wings.forEach(({ wing, side }) => {
        wing.rotation.z = side * Math.sin(time * 14 + index) * 0.9
      })
    })

    // Particles
    for (let i = 0; i < particleCount; i += 1) {
      if (particleLife[i] <= 0) {
        particleAlphas[i] = 0
        continue
      }
      particleLife[i] -= dt
      const t = Math.max(0, particleLife[i] / particleMaxLife[i])
      particleVelocity[i * 3 + 1] -= particleGravity[i] * dt
      particlePositions[i * 3] += particleVelocity[i * 3] * dt
      particlePositions[i * 3 + 1] += particleVelocity[i * 3 + 1] * dt
      particlePositions[i * 3 + 2] += particleVelocity[i * 3 + 2] * dt
      particleAlphas[i] = t * t
    }
    particleGeometry.attributes.position.needsUpdate = true
    particleGeometry.attributes.aAlpha.needsUpdate = true
  }

  function collectApple(apple, effects, audio) {
    if (apple.collected) return false
    apple.collected = true
    apple.group.visible = false
    apple.ring.visible = false
    if (effects) {
      const pos = apple.group.position.clone()
      effects.burst(pos, 0xffd166, 22, { spread: 2.6, up: 5, size: 13, life: 1.1, gravity: 4 })
      effects.burst(pos, 0xfff3c0, 10, { spread: 1.4, up: 3, size: 7, life: 0.8, gravity: 2 })
    }
    if (audio) audio.collect()
    return true
  }

  function resetApples() {
    apples.forEach(apple => {
      apple.collected = false
      apple.group.visible = true
      apple.ring.visible = false
    })
  }

  return {
    root,
    terrain: terrainData,
    minimap,
    apples,
    npcs,
    colliders,
    waterLevel: W.waterLevel,
    spawn: W.spawn,
    update,
    spawnParticles,
    collectApple,
    resetApples,
    getHeight: height,
    clouds: cloudBlobs,
    trail
  }
}

import * as THREE from 'three'
import { height } from './terrain.js'
import { clamp } from './terrain.js'

const WALK_SPEED = 5.6
const GALLOP_SPEED = 10.4
const GRAVITY = 19

function damp(current, target, lambda, dt) {
  return THREE.MathUtils.lerp(current, target, 1 - Math.exp(-lambda * dt))
}

function angleLerp(current, target, lambda, dt) {
  let delta = ((target - current + Math.PI) % (Math.PI * 2)) - Math.PI
  if (delta < -Math.PI) delta += Math.PI * 2
  return current + delta * (1 - Math.exp(-lambda * dt))
}

export class Player {
  constructor(horse, world) {
    this.horse = horse
    this.world = world
    this.position = new THREE.Vector3(world.spawn.x, 0, world.spawn.z)
    this.position.y = world.getHeight(this.position.x, this.position.z)
    this.yaw = world.spawn.yaw
    this.speed = 0
    this.velocityY = 0
    this.grounded = true
    this.stamina = 100
    this.maxStamina = 100
    this.staminaDelay = 0
    this.boost = 1
    this.cameraYaw = this.yaw + Math.PI
    this.cameraPitch = 0.28
    this.cameraDistance = 8.4
    this.cameraTarget = new THREE.Vector3()
    this.moveDir = new THREE.Vector3(Math.sin(this.yaw), 0, Math.cos(this.yaw))
    this.footTimer = 0
    this.splashTimer = 0
    this.inWater = false
    this.jumpLatch = false
    this.cameraInitialized = false
    this.turnTilt = 0
    this.horse.group.position.copy(this.position)
    this.horse.group.rotation.y = this.yaw
    this.cameraTarget.set(this.position.x, this.position.y + 1.9, this.position.z)
  }

  reset() {
    this.position.set(this.world.spawn.x, 0, this.world.spawn.z)
    this.position.y = this.world.getHeight(this.position.x, this.position.z)
    this.yaw = this.world.spawn.yaw
    this.speed = 0
    this.velocityY = 0
    this.grounded = true
    this.stamina = 100
    this.boost = 1
    this.moveDir.set(Math.sin(this.yaw), 0, Math.cos(this.yaw))
    this.cameraYaw = this.yaw + Math.PI
    this.cameraPitch = 0.28
    this.cameraDistance = 8.4
    this.horse.group.position.copy(this.position)
    this.horse.group.rotation.y = this.yaw
    this.cameraInitialized = false
    this.cameraTarget.set(this.position.x, this.position.y + 1.9, this.position.z)
  }

  nearNpc() {
    let closest = null
    let closestDistance = 4.2
    for (const npc of this.world.npcs) {
      const d = Math.hypot(this.position.x - npc.x, this.position.z - npc.z)
      if (d < closestDistance) {
        closest = npc
        closestDistance = d
      }
    }
    return closest
  }

  update(dt, input) {
    const forward = new THREE.Vector3(-Math.sin(this.cameraYaw), 0, -Math.cos(this.cameraYaw))
    const right = new THREE.Vector3(Math.cos(this.cameraYaw), 0, -Math.sin(this.cameraYaw))
    const move = new THREE.Vector3()
    move.addScaledVector(forward, input.forward)
    move.addScaledVector(right, input.strafe)
    const magnitude = Math.min(1, move.length())
    if (magnitude > 0.02) {
      move.normalize()
      this.moveDir.copy(move)
    }

    const wantsGallop = input.gallop && this.stamina > 1 && magnitude > 0.05
    const baseTarget = (wantsGallop ? GALLOP_SPEED : WALK_SPEED) * this.boost * magnitude
    const waterDamp = this.inWater ? 0.55 : 1
    const targetSpeed = baseTarget * waterDamp
    const acceleration = targetSpeed > this.speed ? 7.5 : 9.5
    this.speed = damp(this.speed, targetSpeed, acceleration, dt)

    if (wantsGallop && this.grounded) {
      this.stamina = Math.max(0, this.stamina - 19 * dt)
      this.staminaDelay = 0.6
    } else {
      this.staminaDelay = Math.max(0, this.staminaDelay - dt)
      if (this.staminaDelay === 0) this.stamina = Math.min(this.maxStamina, this.stamina + 15 * dt)
    }

    if (magnitude > 0.05) {
      const desiredYaw = Math.atan2(this.moveDir.x, this.moveDir.z)
      const previous = this.yaw
      this.yaw = angleLerp(this.yaw, desiredYaw, 11, dt)
      let delta = this.yaw - previous
      delta = ((delta + Math.PI) % (Math.PI * 2)) - Math.PI
      this.turnTilt = damp(this.turnTilt, clamp(-delta * 5, -0.16, 0.16), 8, dt)
    } else {
      this.turnTilt = damp(this.turnTilt, 0, 6, dt)
    }

    this.position.x += this.moveDir.x * this.speed * dt
    this.position.z += this.moveDir.z * this.speed * dt

    for (const collider of this.world.colliders) {
      const dx = this.position.x - collider.x
      const dz = this.position.z - collider.z
      const distance = Math.hypot(dx, dz)
      const minimum = collider.r + 0.75
      if (distance < minimum && distance > 0.0001) {
        const push = (minimum - distance) / distance
        this.position.x += dx * push
        this.position.z += dz * push
      }
    }

    const radius = Math.hypot(this.position.x, this.position.z)
    if (radius > 108) {
      this.position.x *= 108 / radius
      this.position.z *= 108 / radius
    }

    const ground = this.world.getHeight(this.position.x, this.position.z)
    const lakeDistance = Math.hypot(this.position.x - (-46), this.position.z - 44)
    this.inWater = ground < this.world.waterLevel - 0.12 && lakeDistance < 26
    const floor = this.inWater ? Math.max(ground, this.world.waterLevel - 0.42) : ground

    if (input.jump && !this.jumpLatch && this.grounded && !this.inWater) {
      this.velocityY = 6.6
      this.grounded = false
      this.jumpLatch = true
      if (input.onJump) input.onJump()
    }
    this.jumpLatch = input.jump

    if (!this.grounded) {
      this.velocityY -= GRAVITY * dt
      this.position.y += this.velocityY * dt
      if (this.position.y <= floor) {
        this.position.y = floor
        if (this.velocityY < -5 && input.onLand) input.onLand()
        this.velocityY = 0
        this.grounded = true
      }
    } else {
      this.position.y = damp(this.position.y, floor, 18, dt)
    }

    this.horse.group.position.copy(this.position)
    this.horse.group.rotation.y = this.yaw
    this.horse.group.rotation.z = damp(this.horse.group.rotation.z, this.turnTilt, 8, dt)

    this.horse.animate(dt, { speed: this.speed, grounded: this.grounded })

    if (this.speed > 0.5 && this.grounded) {
      this.footTimer -= dt
      if (this.footTimer <= 0) {
        this.footTimer = this.speed > 7 ? 0.17 : 0.32
        if (input.onHoof) input.onHoof(this.speed, this.inWater)
        if (!this.inWater) {
          const backX = this.position.x - Math.sin(this.yaw) * 0.5
          const backZ = this.position.z - Math.cos(this.yaw) * 0.5
          this.world.spawnParticles(
            new THREE.Vector3(backX, ground + 0.08, backZ),
            this.speed > 7 ? 0xcdb98f : 0xbfae85,
            this.speed > 7 ? 4 : 2,
            { spread: 0.35, up: 0.8, size: 8, life: 0.45, gravity: 1.8 }
          )
        } else {
          this.world.spawnParticles(
            new THREE.Vector3(this.position.x, this.world.waterLevel + 0.1, this.position.z),
            0xd7f2f4,
            this.speed > 7 ? 6 : 3,
            { spread: 0.8, up: 1.6, size: 7, life: 0.55, gravity: 6 }
          )
        }
      }
    } else {
      this.footTimer = 0
    }
  }

  updateCamera(camera, dt) {
    const target = new THREE.Vector3(
      this.position.x + this.moveDir.x * 0.35,
      this.position.y + 1.95,
      this.position.z + this.moveDir.z * 0.35
    )
    if (!this.cameraInitialized) {
      this.cameraTarget.copy(target)
      this.cameraInitialized = true
    } else {
      this.cameraTarget.lerp(target, 1 - Math.exp(-dt * 10))
    }

    const cosPitch = Math.cos(this.cameraPitch)
    const offset = new THREE.Vector3(
      Math.sin(this.cameraYaw) * cosPitch,
      Math.sin(this.cameraPitch),
      Math.cos(this.cameraYaw) * cosPitch
    ).multiplyScalar(this.cameraDistance)
    const desired = this.cameraTarget.clone().add(offset)
    const terrainAtCamera = this.world.getHeight(desired.x, desired.z)
    desired.y = Math.max(desired.y, terrainAtCamera + 1.15)

    // Pull the camera in when a ridge would block the view.
    const steps = 7
    for (let i = 1; i <= steps; i += 1) {
      const t = i / steps
      const sampleX = THREE.MathUtils.lerp(this.cameraTarget.x, desired.x, t)
      const sampleZ = THREE.MathUtils.lerp(this.cameraTarget.z, desired.z, t)
      const sampleY = THREE.MathUtils.lerp(this.cameraTarget.y, desired.y, t)
      const ground = this.world.getHeight(sampleX, sampleZ)
      if (sampleY < ground + 0.7) {
        const safeT = Math.max(0.18, t - 0.12)
        desired.x = THREE.MathUtils.lerp(this.cameraTarget.x, desired.x, safeT)
        desired.y = THREE.MathUtils.lerp(this.cameraTarget.y, desired.y, safeT)
        desired.z = THREE.MathUtils.lerp(this.cameraTarget.z, desired.z, safeT)
        break
      }
    }

    camera.position.lerp(desired, 1 - Math.exp(-dt * 7.5))
    camera.lookAt(this.cameraTarget)
    camera.rotation.z += this.turnTilt * 0.08
  }
}

export class AudioKit {
  constructor() {
    this.ctx = null
    this.master = null
    this.windGain = null
    this.muted = false
    this.birdTimer = 3
    this.started = false
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume()
      return
    }
    const Ctx = window.AudioContext || window.webkitAudioContext
    if (!Ctx) return
    this.ctx = new Ctx()
    this.master = this.ctx.createGain()
    this.master.gain.value = this.muted ? 0 : 0.55
    this.master.connect(this.ctx.destination)
    this.startAmbience()
    this.started = true
  }

  startAmbience() {
    if (!this.ctx) return
    const length = this.ctx.sampleRate * 2
    const buffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate)
    const data = buffer.getChannelData(0)
    for (let i = 0; i < length; i += 1) data[i] = Math.random() * 2 - 1
    const source = this.ctx.createBufferSource()
    source.buffer = buffer
    source.loop = true
    const filter = this.ctx.createBiquadFilter()
    filter.type = 'lowpass'
    filter.frequency.value = 420
    filter.Q.value = 0.6
    const gain = this.ctx.createGain()
    gain.gain.value = 0.055
    source.connect(filter).connect(gain).connect(this.master)
    source.start()
    this.windGain = gain
    this.windSource = source
  }

  setMuted(muted) {
    this.muted = muted
    if (this.master && this.ctx) {
      this.master.gain.setTargetAtTime(muted ? 0 : 0.55, this.ctx.currentTime, 0.05)
    }
  }

  noiseBurst(duration = 0.12, volume = 0.18, frequency = 900) {
    if (!this.ctx) return
    const length = Math.floor(this.ctx.sampleRate * duration)
    const buffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate)
    const data = buffer.getChannelData(0)
    for (let i = 0; i < length; i += 1) data[i] = (Math.random() * 2 - 1) * (1 - i / length)
    const source = this.ctx.createBufferSource()
    source.buffer = buffer
    const filter = this.ctx.createBiquadFilter()
    filter.type = 'bandpass'
    filter.frequency.value = frequency
    filter.Q.value = 0.9
    const gain = this.ctx.createGain()
    gain.gain.value = volume
    source.connect(filter).connect(gain).connect(this.master)
    source.start()
  }

  tone(frequency, duration = 0.15, { type = 'sine', volume = 0.16, delay = 0, slide = 0, attack = 0.008 } = {}) {
    if (!this.ctx) return
    const start = this.ctx.currentTime + delay
    const oscillator = this.ctx.createOscillator()
    const gain = this.ctx.createGain()
    oscillator.type = type
    oscillator.frequency.setValueAtTime(frequency, start)
    if (slide) oscillator.frequency.exponentialRampToValueAtTime(Math.max(20, slide), start + duration)
    gain.gain.setValueAtTime(0.0001, start)
    gain.gain.exponentialRampToValueAtTime(volume, start + attack)
    gain.gain.exponentialRampToValueAtTime(0.0001, start + duration)
    oscillator.connect(gain).connect(this.master)
    oscillator.start(start)
    oscillator.stop(start + duration + 0.05)
  }

  hoof(speed, water = false) {
    if (!this.ctx) return
    const heavy = speed > 7
    if (water) {
      this.noiseBurst(0.18, heavy ? 0.14 : 0.08, 1400)
      return
    }
    this.tone(heavy ? 72 : 88, 0.1, { type: 'sine', volume: heavy ? 0.2 : 0.12, slide: 42 })
    this.noiseBurst(0.06, heavy ? 0.08 : 0.05, 700)
  }

  jump() {
    this.tone(210, 0.18, { type: 'triangle', volume: 0.09, slide: 440 })
  }

  land() {
    this.tone(90, 0.16, { type: 'sine', volume: 0.16, slide: 45 })
    this.noiseBurst(0.1, 0.08, 500)
  }

  collect() {
    if (!this.ctx) return
    const notes = [880, 1108.73, 1318.51, 1760]
    notes.forEach((note, index) => {
      this.tone(note, 0.24, { type: 'triangle', volume: 0.12, delay: index * 0.055 })
    })
    this.noiseBurst(0.12, 0.03, 2600)
  }

  quest() {
    if (!this.ctx) return
    const notes = [523.25, 659.25, 783.99, 1046.5, 1318.51, 1567.98]
    notes.forEach((note, index) => {
      this.tone(note, 0.5, { type: 'triangle', volume: 0.14, delay: index * 0.11 })
      this.tone(note / 2, 0.5, { type: 'sine', volume: 0.07, delay: index * 0.11 })
    })
    this.tone(2093, 1.1, { type: 'sine', volume: 0.06, delay: 0.7 })
  }

  click() {
    this.tone(520, 0.07, { type: 'triangle', volume: 0.1 })
    this.tone(780, 0.06, { type: 'sine', volume: 0.06, delay: 0.03 })
  }

  blip() {
    this.tone(640 + Math.random() * 160, 0.06, { type: 'triangle', volume: 0.05 })
  }

  chirp() {
    if (!this.ctx) return
    const base = 1800 + Math.random() * 900
    const notes = 2 + Math.floor(Math.random() * 3)
    for (let i = 0; i < notes; i += 1) {
      this.tone(base + Math.random() * 500, 0.09, {
        type: 'sine',
        volume: 0.025,
        delay: i * 0.11,
        slide: base * (0.8 + Math.random() * 0.5)
      })
    }
  }

  update(dt) {
    if (!this.ctx || this.muted) return
    this.birdTimer -= dt
    if (this.birdTimer < 0) {
      this.birdTimer = 4 + Math.random() * 7
      if (this.started) this.chirp()
    }
  }
}

@font-face {
  font-family: 'Fredoka';
  src: url('./src/assets/fredoka.woff2') format('woff2');
  font-weight: 300 700;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Nunito';
  src: url('./src/assets/nunito.woff2') format('woff2');
  font-weight: 200 900;
  font-style: normal;
  font-display: swap;
}

:root {
  --ink: #3b2a1c;
  --ink-soft: #6b543d;
  --brown: #5c3a1c;
  --brown-soft: #8b674a;
  --cream: #fff8e8;
  --cream-deep: #f7e6c4;
  --gold: #ffc83d;
  --gold-deep: #f0a51c;
  --green: #4fc06a;
  --green-deep: #2f7c45;
  --pink: #f28cb0;
  --sky: #9fd8ff;
  --shadow: 0 6px 0 rgba(92, 58, 28, 0.2), 0 18px 38px rgba(60, 40, 20, 0.2);
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
}

* { box-sizing: border-box; }

html, body {
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: #f0dcb6;
  color: var(--ink);
  font-family: 'Nunito', 'Trebuchet MS', sans-serif;
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
}

body { overscroll-behavior: none; }

#app, #scene {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
}
#scene { display: block; touch-action: none; }

#vignette {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 4;
  background:
    linear-gradient(180deg, rgba(255, 236, 191, 0.14), transparent 18%, transparent 78%, rgba(52, 34, 14, 0.18)),
    radial-gradient(ellipse at center, transparent 52%, rgba(49, 30, 11, 0.28) 100%);
  mix-blend-mode: multiply;
}

.screen { position: fixed; inset: 0; z-index: 20; }
.hidden { display: none !important; }

/* Generic UI ------------------------------------------------------------- */
.glass {
  background: rgba(255, 250, 238, 0.88);
  border: 2px solid rgba(92, 58, 28, 0.82);
  box-shadow: 0 4px 0 rgba(92, 58, 28, 0.16), 0 14px 26px rgba(64, 42, 18, 0.16);
  -webkit-backdrop-filter: blur(9px);
  backdrop-filter: blur(9px);
}

.card {
  background: linear-gradient(165deg, rgba(255, 251, 240, 0.97), rgba(252, 239, 214, 0.94));
  border: 3px solid var(--brown);
  border-radius: 26px;
  box-shadow: 0 10px 0 rgba(92, 58, 28, 0.22), 0 24px 46px rgba(64, 42, 18, 0.26), inset 0 1px 0 rgba(255, 255, 255, 0.9);
  padding: 24px;
}

.eyebrow {
  display: block;
  font-family: 'Fredoka', sans-serif;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--brown-soft);
  margin-bottom: 4px;
}

h2, h3, .logo, .btn, .apple-pill strong, .quest strong, .player-copy strong, .name-chip, .stamina-label, .round-btn, kbd {
  font-family: 'Fredoka', sans-serif;
}

h2 { margin: 0; font-size: 30px; line-height: 1; font-weight: 600; letter-spacing: 0.01em; }
h3 { margin: 0 0 12px; font-size: 20px; font-weight: 600; }

.btn {
  appearance: none;
  border: 3px solid var(--brown);
  border-radius: 16px;
  background: var(--cream);
  color: var(--ink);
  font-size: 18px;
  font-weight: 600;
  padding: 12px 22px;
  cursor: pointer;
  box-shadow: 0 5px 0 var(--brown);
  transition: transform 0.12s ease, box-shadow 0.12s ease, background 0.12s ease;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  line-height: 1;
  user-select: none;
}
.btn:hover { transform: translateY(-1px); box-shadow: 0 6px 0 var(--brown); background: #fffdf6; }
.btn:active { transform: translateY(4px); box-shadow: 0 1px 0 var(--brown); }
.btn.primary {
  background: linear-gradient(180deg, #6ed989, var(--green) 45%, #43b45f);
  border-color: var(--green-deep);
  box-shadow: 0 5px 0 var(--green-deep), inset 0 2px 0 rgba(255, 255, 255, 0.35);
  color: #fffdf4;
  text-shadow: 0 1px 0 rgba(34, 92, 49, 0.55);
  min-height: 50px;
}
.btn.primary:hover { background: linear-gradient(180deg, #7ee59a, #57c874 45%, #47bc64); box-shadow: 0 6px 0 var(--green-deep), inset 0 2px 0 rgba(255, 255, 255, 0.35); }
.btn.primary:active { box-shadow: 0 1px 0 var(--green-deep), inset 0 2px 0 rgba(255, 255, 255, 0.35); }
.btn.ghost { background: transparent; box-shadow: none; border-color: rgba(92, 58, 28, 0.4); color: var(--ink-soft); }
.btn.ghost:hover { background: rgba(255, 255, 255, 0.4); box-shadow: none; }
.btn:focus-visible, .icon-btn:focus-visible, .swatch:focus-visible, .round-btn:focus-visible, input:focus-visible {
  outline: 3px solid #2e8bff;
  outline-offset: 3px;
}

kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 26px;
  height: 26px;
  padding: 0 6px;
  font-size: 12px;
  color: var(--ink);
  background: #fffdf7;
  border: 2px solid rgba(92, 58, 28, 0.55);
  border-bottom-width: 3px;
  border-radius: 7px;
  font-weight: 600;
  line-height: 1;
}

/* Loading ---------------------------------------------------------------- */
.overlay {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: radial-gradient(circle at 50% 28%, #fff0c7 0%, #f2d9a5 46%, #d7ae6f 100%);
  transition: opacity 0.55s ease;
}
.overlay.leaving { opacity: 0; pointer-events: none; }
.loading-mark { width: 92px; height: 92px; color: var(--brown); animation: bob 2.2s ease-in-out infinite; filter: drop-shadow(0 7px 0 rgba(92, 58, 28, 0.16)); }
.loading-mark svg { width: 100%; height: 100%; }
.loading-title { font-family: 'Fredoka', sans-serif; font-size: 44px; font-weight: 600; margin: 0; color: var(--brown); letter-spacing: 0.02em; }
.loading-bar { width: 230px; height: 14px; border: 3px solid var(--brown); border-radius: 99px; background: rgba(255, 249, 233, 0.6); overflow: hidden; margin-top: 6px; }
.loading-bar i { display: block; height: 100%; width: 42%; border-radius: 99px; background: repeating-linear-gradient(115deg, var(--gold) 0 12px, #ffd968 12px 24px); animation: load 1.3s ease-in-out infinite; }
.loading-sub { margin: 10px 0 0; font-weight: 700; color: var(--brown-soft); font-size: 14px; letter-spacing: 0.02em; }
@keyframes load { 0% { transform: translateX(-45%); } 100% { transform: translateX(280%); } }
@keyframes bob { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-9px); } }

/* Title screen ------------------------------------------------------------ */
#start-screen {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 20px;
  padding: clamp(18px, 3.2vw, 46px);
  padding-top: calc(clamp(18px, 3.2vw, 46px) + var(--safe-top));
  padding-bottom: calc(clamp(18px, 3.2vw, 46px) + var(--safe-bottom));
  background:
    linear-gradient(180deg, rgba(255, 243, 207, 0.18) 0%, transparent 26%, transparent 55%, rgba(55, 35, 14, 0.38) 100%),
    linear-gradient(100deg, rgba(255, 244, 213, 0.4) 0%, transparent 46%);
  transition: opacity 0.5s ease;
  pointer-events: none;
}
#start-screen.leaving { opacity: 0; }
#start-screen > * { pointer-events: auto; }
#start-screen .logo-block { pointer-events: none; }

.start-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 22px; }
.logo-block { max-width: 640px; }
.logo-kicker {
  display: inline-block;
  font-family: 'Fredoka', sans-serif;
  font-size: clamp(9px, 1vw, 12px);
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--brown);
  background: rgba(255, 247, 225, 0.9);
  border: 2px solid rgba(92, 58, 28, 0.7);
  border-radius: 999px;
  padding: 7px 14px;
  box-shadow: 0 4px 0 rgba(92, 58, 28, 0.16);
  margin-bottom: 14px;
}
.logo {
  margin: 0;
  font-size: clamp(58px, 8.6vw, 118px);
  line-height: 0.8;
  font-weight: 700;
  letter-spacing: 0.005em;
  color: #fff8e2;
  text-shadow:
    0 4px 0 #efbd62,
    0 9px 0 #bd7f37,
    0 14px 0 #7d4c22,
    0 20px 30px rgba(66, 40, 13, 0.4);
}
.logo span { display: block; color: #ffd04d; margin-left: clamp(6px, 1.4vw, 24px); }
.tagline {
  max-width: 470px;
  margin: 20px 0 0;
  color: #fff9e8;
  font-size: clamp(14px, 1.25vw, 17px);
  font-weight: 700;
  line-height: 1.45;
  text-shadow: 0 2px 0 rgba(83, 51, 18, 0.45), 0 6px 16px rgba(66, 40, 13, 0.35);
}
.logo-badges { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }
.badge {
  font-family: 'Fredoka', sans-serif;
  font-size: 12px;
  font-weight: 600;
  color: var(--brown);
  background: rgba(255, 248, 227, 0.88);
  border: 2px solid rgba(92, 58, 28, 0.6);
  border-radius: 999px;
  padding: 6px 12px;
  box-shadow: 0 3px 0 rgba(92, 58, 28, 0.14);
}
.start-tip {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border-radius: 999px;
  background: rgba(63, 42, 20, 0.38);
  color: #fff8e6;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.02em;
  -webkit-backdrop-filter: blur(5px);
  backdrop-filter: blur(5px);
  white-space: nowrap;
}
.start-tip .dot { width: 8px; height: 8px; border-radius: 50%; background: #a6f08a; box-shadow: 0 0 0 4px rgba(166, 240, 138, 0.18); }

.start-bottom { display: flex; align-items: flex-end; justify-content: space-between; gap: 26px; }
.controls-card { width: 286px; flex: 0 0 auto; }
.key-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 9px; }
.key-list li { display: flex; align-items: center; justify-content: space-between; gap: 10px; font-size: 13px; font-weight: 800; color: var(--ink-soft); }
.keys { display: flex; gap: 3px; }
.tiny { margin: 14px 0 0; font-size: 11.5px; line-height: 1.45; color: var(--brown-soft); font-weight: 700; }

.customize-card { width: 404px; flex: 0 0 auto; }
.card-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; margin-bottom: 14px; }
.name-chip {
  display: inline-flex;
  align-items: center;
  height: 32px;
  padding: 0 12px;
  border-radius: 999px;
  background: var(--gold);
  border: 2px solid var(--brown);
  font-size: 13px;
  font-weight: 600;
  color: var(--brown);
  box-shadow: 0 3px 0 rgba(92, 58, 28, 0.25);
  white-space: nowrap;
}
.field { display: flex; align-items: center; gap: 10px; margin-bottom: 14px; }
.field > span { font-size: 12px; font-weight: 800; text-transform: uppercase; letter-spacing: 0.1em; color: var(--brown-soft); }
.field input {
  flex: 1;
  min-width: 0;
  height: 44px;
  border: 2.5px solid var(--brown);
  border-radius: 12px;
  background: #fffdf7;
  padding: 0 14px;
  font-family: 'Fredoka', sans-serif;
  font-size: 18px;
  font-weight: 600;
  color: var(--ink);
  box-shadow: inset 0 2px 5px rgba(92, 58, 28, 0.08);
}
.swatch-block { margin-bottom: 13px; }
.swatch-title { display: flex; justify-content: space-between; align-items: center; margin-bottom: 7px; }
.swatch-title span { font-size: 12px; font-weight: 800; text-transform: uppercase; letter-spacing: 0.1em; color: var(--brown-soft); }
.swatch-title em { font-style: normal; font-family: 'Fredoka', sans-serif; font-size: 12px; font-weight: 600; color: var(--brown); }
.swatches { display: flex; flex-wrap: wrap; gap: 8px; }
.swatch {
  width: 33px;
  height: 33px;
  border-radius: 50%;
  border: 2.5px solid rgba(92, 58, 28, 0.7);
  box-shadow: 0 3px 0 rgba(92, 58, 28, 0.2), inset 0 2px 0 rgba(255, 255, 255, 0.35);
  cursor: pointer;
  position: relative;
  padding: 0;
  transition: transform 0.12s ease;
}
.swatch:hover { transform: translateY(-2px) scale(1.04); }
.swatch.selected { border-color: #2b6b3d; box-shadow: 0 0 0 3px #fff8e8, 0 0 0 5px var(--green-deep), 0 4px 0 rgba(47, 124, 69, 0.3); }
.swatch.selected::after {
  content: '';
  position: absolute;
  inset: 0;
  margin: auto;
  width: 10px;
  height: 6px;
  border-left: 3px solid #fff;
  border-bottom: 3px solid #fff;
  transform: rotate(-45deg) translate(1px, -1px);
  filter: drop-shadow(0 1px 1px rgba(0, 0, 0, 0.35));
}
.play-btn { width: 100%; margin-top: 4px; font-size: 22px; padding: 14px 22px; }
.play-btn svg { width: 22px; height: 22px; }
.start-meta { display: flex; justify-content: center; gap: 7px; margin-top: 11px; font-size: 10.5px; font-weight: 800; color: var(--brown-soft); letter-spacing: 0.01em; }
.start-footer {
  margin: 0;
  font-size: 10.5px;
  font-weight: 700;
  color: rgba(255, 249, 232, 0.85);
  text-shadow: 0 1px 3px rgba(55, 35, 14, 0.5);
  text-align: right;
}

/* HUD --------------------------------------------------------------------- */
#hud { pointer-events: none; }
#hud button, #hud .minimap-wrap { pointer-events: auto; }

.hud-top {
  position: absolute;
  top: calc(16px + var(--safe-top));
  left: 16px;
  right: 16px;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: start;
  gap: 12px;
}
.player-card {
  justify-self: start;
  display: flex;
  align-items: center;
  gap: 10px;
  border-radius: 999px;
  padding: 7px 16px 7px 8px;
  min-width: 190px;
}
.avatar-dot {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #fff, #d9c4a5 40%, #a47a52 100%);
  border: 2.5px solid var(--brown);
  box-shadow: 0 3px 0 rgba(92, 58, 28, 0.2);
  flex: 0 0 auto;
}
.player-copy { display: flex; flex-direction: column; line-height: 1.05; }
.player-copy strong { font-size: 18px; font-weight: 600; color: var(--ink); }
.player-copy em { font-style: normal; font-size: 10.5px; font-weight: 800; letter-spacing: 0.08em; text-transform: uppercase; color: var(--brown-soft); }

.apple-pill {
  justify-self: center;
  display: grid;
  grid-template-columns: auto auto;
  grid-template-rows: auto auto;
  align-items: center;
  column-gap: 9px;
  padding: 8px 18px 8px 10px;
  border-radius: 20px;
  background: linear-gradient(180deg, #fff8df, #ffe9ad);
}
.apple-icon {
  grid-row: 1 / 3;
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  color: #e89b12;
  background: #fff4cf;
  border: 2.5px solid var(--brown);
  border-radius: 13px;
  filter: drop-shadow(0 2px 0 rgba(92, 58, 28, 0.15));
}
.apple-icon svg { width: 24px; height: 24px; }
.apple-copy { display: flex; align-items: baseline; gap: 3px; line-height: 1; }
.apple-copy strong { font-size: 27px; font-weight: 700; color: var(--brown); }
.apple-copy em { font-style: normal; font-size: 15px; font-weight: 800; color: var(--brown-soft); }
.apple-label { font-size: 9.5px; font-weight: 900; letter-spacing: 0.12em; text-transform: uppercase; color: var(--brown-soft); margin-top: 1px; }

.hud-actions { justify-self: end; display: flex; gap: 8px; }
.icon-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 2px solid rgba(92, 58, 28, 0.82);
  display: grid;
  place-items: center;
  color: var(--brown);
  cursor: pointer;
  box-shadow: 0 4px 0 rgba(92, 58, 28, 0.2);
  transition: transform 0.12s ease;
}
.icon-btn:hover { transform: translateY(-2px); }
.icon-btn:active { transform: translateY(2px); }
.icon-btn svg { width: 22px; height: 22px; }
.icon-off { display: none; }
#sound-btn.muted .icon-on { display: none; }
#sound-btn.muted .icon-off { display: block; }

.minimap-wrap {
  position: absolute;
  top: calc(74px + var(--safe-top));
  right: 16px;
  width: 178px;
  height: 178px;
  border-radius: 50%;
  overflow: hidden;
  border-width: 3px;
  box-shadow: 0 6px 0 rgba(92, 58, 28, 0.22), 0 16px 28px rgba(64, 42, 18, 0.22);
  background: #cfe3b8;
}
.minimap-wrap canvas { width: 100%; height: 100%; display: block; }
.compass {
  position: absolute;
  top: 7px;
  left: 50%;
  transform: translateX(-50%);
  font-family: 'Fredoka', sans-serif;
  font-size: 12px;
  font-weight: 700;
  color: #fff8e5;
  background: rgba(72, 48, 22, 0.72);
  width: 22px;
  height: 22px;
  border-radius: 50%;
  display: grid;
  place-items: center;
}
.minimap-label {
  position: absolute;
  bottom: 17px;
  left: 50%;
  transform: translateX(-50%);
  font-family: 'Fredoka', sans-serif;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.08em;
  color: #fff9e9;
  background: rgba(72, 48, 22, 0.66);
  padding: 3px 10px;
  border-radius: 999px;
  white-space: nowrap;
}

.quest {
  position: absolute;
  top: calc(76px + var(--safe-top));
  left: 16px;
  width: 246px;
  border-radius: 18px;
  padding: 12px 15px 14px;
}
.quest-kicker { font-family: 'Fredoka', sans-serif; font-size: 9px; font-weight: 600; letter-spacing: 0.18em; text-transform: uppercase; color: var(--brown-soft); }
