const STAR_SVG = '<svg viewBox="0 0 24 24"><path d="M12 3.2l2.5 5.4 5.9.7-4.4 4 1.2 5.9L12 16.3l-5.2 2.9 1.2-5.9-4.4-4 5.9-.7z" fill="currentColor"/></svg>'

function hex(value) {
  return `#${value.toString(16).padStart(6, '0')}`
}

function lighten(value, amount) {
  const r = Math.min(255, ((value >> 16) & 255) + amount)
  const g = Math.min(255, ((value >> 8) & 255) + amount)
  const b = Math.min(255, (value & 255) + amount)
  return `rgb(${r}, ${g}, ${b})`
}

export class UI {
  constructor({ coats, manes, handlers }) {
    this.coats = coats
    this.manes = manes
    this.handlers = handlers
    this.coatIndex = 0
    this.maneIndex = 0
    this.appleTotal = 12
    this.lastMinimap = 0
    this.toasts = []
    this.muted = false

    this.el = {
      start: document.getElementById('start-screen'),
      hud: document.getElementById('hud'),
      loading: document.getElementById('loading'),
      play: document.getElementById('play-btn'),
      name: document.getElementById('horse-name'),
      nameChip: document.getElementById('horse-name-chip'),
      hudName: document.getElementById('hud-name'),
      pauseName: document.getElementById('pause-name'),
      coatSwatches: document.getElementById('coat-swatches'),
      maneSwatches: document.getElementById('mane-swatches'),
      pauseCoatSwatches: document.getElementById('pause-coat-swatches'),
      pauseManeSwatches: document.getElementById('pause-mane-swatches'),
      coatName: document.getElementById('coat-name'),
      maneName: document.getElementById('mane-name'),
      pauseCoatName: document.getElementById('pause-coat-name'),
      pauseManeName: document.getElementById('pause-mane-name'),
      appleCount: document.getElementById('apple-count'),
      applePill: document.querySelector('.apple-pill'),
      questFill: document.getElementById('quest-fill'),
      questTitle: document.getElementById('quest-title'),
      questDesc: document.getElementById('quest-desc'),
      stamina: document.querySelector('.stamina'),
      staminaFill: document.getElementById('stamina-fill'),
      prompt: document.getElementById('interact-prompt'),
      promptText: document.getElementById('interact-text'),
      toastStack: document.getElementById('toast-stack'),
      dialog: document.getElementById('dialog'),
      dialogAvatar: document.getElementById('dialog-avatar'),
      dialogName: document.getElementById('dialog-name'),
      dialogRole: document.getElementById('dialog-role'),
      dialogText: document.getElementById('dialog-text'),
      dialogNext: document.getElementById('dialog-next'),
      pause: document.getElementById('pause-menu'),
      complete: document.getElementById('complete'),
      statTime: document.getElementById('stat-time'),
      continueBtn: document.getElementById('continue-btn'),
      resume: document.getElementById('resume-btn'),
      restart: document.getElementById('restart-btn'),
      quit: document.getElementById('quit-btn'),
      sound: document.getElementById('sound-btn'),
      pauseBtn: document.getElementById('pause-btn'),
      minimap: document.getElementById('minimap'),
      mobile: document.getElementById('mobile-controls'),
      joystick: document.getElementById('joystick'),
      stick: document.getElementById('stick'),
      gallop: document.getElementById('gallop-btn'),
      jump: document.getElementById('jump-btn'),
      avatar: document.getElementById('avatar-dot')
    }

    this.minimapContext = this.el.minimap.getContext('2d')
    this.isTouch = window.matchMedia('(pointer: coarse)').matches || window.matchMedia('(max-width: 860px)').matches
    if (this.isTouch) document.body.classList.add('touch')
    this.bindStart()
    this.bindHud()
    this.bindDialogs()
    this.bindMobile()
    this.renderSwatches()
    this.setCoat(0, false)
    this.setMane(0, false)
    this.bindResponsive()
  }

  bindResponsive() {
    const query = window.matchMedia('(max-width: 860px)')
    const update = () => {
      this.isTouch = query.matches || window.matchMedia('(pointer: coarse)').matches
      document.body.classList.toggle('touch', this.isTouch)
      if (!this.el.mobile.classList.contains('hidden')) {
        this.el.mobile.classList.toggle('hidden', !this.isTouch)
      }
    }
    query.addEventListener('change', update)
  }

  bindStart() {
    this.el.play.addEventListener('click', () => this.handlers.onPlay())
    this.el.name.addEventListener('input', () => {
      const value = this.el.name.value.slice(0, 12)
      this.setName(value)
      this.handlers.onName??.(value)
    })
    this.el.name.addEventListener('keydown', event => {
      if (event.key === 'Enter') this.el.play.click()
    })
  }

  bindHud() {
    this.el.sound.addEventListener('click', () => this.handlers.onSound())
    this.el.pauseBtn.addEventListener('click', () => this.handlers.onPause())
  }

  bindDialogs() {
    this.el.dialogNext.addEventListener('click', () => this.handlers.onDialogClose())
    this.el.continueBtn.addEventListener('click', () => this.handlers.onContinue())
    this.el.resume.addEventListener('click', () => this.handlers.onResume())
    this.el.restart.addEventListener('click', () => this.handlers.onRestart())
    this.el.quit.addEventListener('click', () => this.handlers.onQuit())
    window.addEventListener('keydown', event => {
      if (event.key === 'Escape') {
        if (!this.el.dialog.classList.contains('hidden')) this.handlers.onDialogClose()
        else if (!this.el.complete.classList.contains('hidden')) this.handlers.onContinue()
        else if (!this.el.pause.classList.contains('hidden')) this.handlers.onResume()
        else this.handlers.onPause()
      }
    })
  }

  bindMobile() {
    let pointerId = null
    const moveStick = event => {
      const rect = this.el.joystick.getBoundingClientRect()
      const centerX = rect.left + rect.width / 2
      const centerY = rect.top + rect.height / 2
      let dx = event.clientX - centerX
      let dy = event.clientY - centerY
      const max = rect.width * 0.32
      const length = Math.hypot(dx, dy)
      if (length > max) {
        dx = (dx / length) * max
        dy = (dy / length) * max
      }
      this.el.stick.style.transform = `translate(${dx}px, ${dy}px)`
      this.handlers.onJoystick(dx / max, -dy / max)
    }
    const release = () => {
      pointerId = null
      this.el.stick.style.transform = 'translate(0, 0)'
      this.handlers.onJoystick(0, 0)
    }
    this.el.joystick.addEventListener('pointerdown', event => {
      pointerId = event.pointerId
      this.el.joystick.setPointerCapture(pointerId)
      moveStick(event)
      event.preventDefault()
    })
    this.el.joystick.addEventListener('pointermove', event => {
      if (event.pointerId !== pointerId) return
      moveStick(event)
      event.preventDefault()
    })
    this.el.joystick.addEventListener('pointerup', release)
    this.el.joystick.addEventListener('pointercancel', release)
    this.el.joystick.addEventListener('pointerleave', event => {
      if (pointerId !== null && event.pointerId === pointerId && !this.el.joystick.hasPointerCapture(pointerId)) release()
    })

    const gallopOn = event => {
      this.handlers.onGallop(true)
      event.preventDefault()
    }
    const gallopOff = event => {
      this.handlers.onGallop(false)
      event?.preventDefault?.()
    }
    this.el.gallop.addEventListener('pointerdown', gallopOn)
    this.el.gallop.addEventListener('pointerup', gallopOff)
    this.el.gallop.addEventListener('pointercancel', gallopOff)
    this.el.gallop.addEventListener('pointerleave', gallopOff)
    this.el.jump.addEventListener('pointerdown', event => {
      this.handlers.onJump()
      event.preventDefault()
    })
  }

  renderSwatches() {
    const create = (item, type, index, target) => {
      const button = document.createElement('button')
      button.type = 'button'
      button.className = 'swatch'
      button.dataset.index = String(index)
      button.dataset.type = type
      button.setAttribute('aria-label', item.name)
      button.title = item.name
      button.style.background = type === 'coat'
        ? `linear-gradient(140deg, ${lighten(item.body, 26)} 0%, ${hex(item.body)} 52%, ${hex(item.shade)} 100%)`
        : `linear-gradient(140deg, ${lighten(item.color, 26)} 0%, ${hex(item.color)} 70%)`
      button.addEventListener('click', () => {
        if (type === 'coat') this.setCoat(index, true)
        else this.setMane(index, true)
      })
      target.appendChild(button)
    }
    this.coats.forEach((item, index) => create(item, 'coat', index, this.el.coatSwatches))
    this.manes.forEach((item, index) => create(item, 'mane', index, this.el.maneSwatches))
    this.coats.forEach((item, index) => create(item, 'coat', index, this.el.pauseCoatSwatches))
    this.manes.forEach((item, index) => create(item, 'mane', index, this.el.pauseManeSwatches))
  }

  setCoat(index, notify = true) {
    this.coatIndex = index
    const coat = this.coats[index]
    for (const container of [this.el.coatSwatches, this.el.pauseCoatSwatches]) {
      container.querySelectorAll('.swatch').forEach(button => {
        button.classList.toggle('selected', Number(button.dataset.index) === index)
      })
    }
    this.el.coatName.textContent = coat.name
    this.el.pauseCoatName.textContent = coat.name
    this.el.avatar.style.background = `radial-gradient(circle at 35% 30%, ${lighten(coat.body, 40)}, ${hex(coat.body)} 55%, ${hex(coat.shade)})`
    if (notify) this.handlers.onCoat?.(index)
  }

  setMane(index, notify = true) {
    this.maneIndex = index
    const mane = this.manes[index]
    for (const container of [this.el.maneSwatches, this.el.pauseManeSwatches]) {
      container.querySelectorAll('.swatch').forEach(button => {
        button.classList.toggle('selected', Number(button.dataset.index) === index)
      })
    }
    this.el.maneName.textContent = mane.name
    this.el.pauseManeName.textContent = mane.name
    if (notify) this.handlers.onMane?.(index)
  }

  setName(value) {
    const clean = value.trim() || 'Comet'
    this.el.nameChip.textContent = clean
    this.el.hudName.textContent = clean
    this.el.pauseName.textContent = clean
  }

  setMuted(muted) {
    this.muted = muted
    this.el.sound.classList.toggle('muted', muted)
    this.el.sound.setAttribute('aria-label', muted ? 'Unmute sound' : 'Mute sound')
    this.el.sound.title = muted ? 'Unmute sound' : 'Mute sound'
  }

  hideLoading() {
    this.el.loading.classList.add('leaving')
    window.setTimeout(() => this.el.loading.classList.add('hidden'), 600)
  }

  showGame() {
    this.el.start.classList.add('leaving')
    window.setTimeout(() => this.el.start.classList.add('hidden'), 520)
    this.el.hud.classList.remove('hidden')
    if (this.isTouch) this.el.mobile.classList.remove('hidden')
  }

  showTitle() {
    this.el.start.classList.remove('hidden', 'leaving')
    this.el.hud.classList.add('hidden')
    this.el.mobile.classList.add('hidden')
    this.el.pause.classList.add('hidden')
    this.el.dialog.classList.add('hidden')
    this.el.complete.classList.add('hidden')
    this.hidePrompt()
  }

  updateApples(count, total = 12) {
    this.el.appleCount.textContent = String(count)
    this.el.questFill.style.width = `${Math.min(100, (count / total) * 100)}%`
  }

  completeQuest() {
    this.el.questTitle.textContent = 'Valley Hero'
    this.el.questDesc.textContent = "June's lucky horseshoe is yours. Keep exploring!"
    this.el.questFill.style.width = '100%'
  }

  updateStamina(value) {
    this.el.staminaFill.style.transform = `scaleX(${Math.max(0.001, value / 100)})`
    this.el.stamina.classList.toggle('empty', value < 8)
  }

  showPrompt(text) {
    this.el.promptText.textContent = text
    this.el.prompt.classList.remove('hidden')
  }

  hidePrompt() {
    this.el.prompt.classList.add('hidden')
  }

  toast(text, icon = 'apple') {
    const toast = document.createElement('div')
    toast.className = 'toast'
    toast.innerHTML = `<span class="toast-icon">${icon === 'star' ? STAR_SVG : APPLE_SVG}</span><span>${text}</span>`
    this.el.toastStack.appendChild(toast)
    this.toasts.push(toast)
    while (this.toasts.length > 3) {
      const first = this.toasts.shift()
      first.remove()
    }
    window.setTimeout(() => {
      toast.classList.add('out')
      window.setTimeout(() => {
        toast.remove()
        this.toasts = this.toasts.filter(item => item !== toast)
      }, 420)
    }, 2400)
  }

  openDialog({ name, role, initial, text, button = "Let's ride!" }) {
    this.el.dialogName.textContent = name
    this.el.dialogRole.textContent = role
    this.el.dialogAvatar.textContent = initial
    this.el.dialogText.textContent = text
    this.el.dialogNext.textContent = button
    this.el.dialog.classList.remove('hidden')
  }

  closeDialog() {
    this.el.dialog.classList.add('hidden')
  }

  showPause() {
    this.el.pause.classList.remove('hidden')
  }

  hidePause() {
    this.el.pause.classList.add('hidden')
  }

  showComplete({ time }) {
    this.el.statTime.textContent = time
    this.el.complete.classList.remove('hidden')
  }

  hideComplete() {
    this.el.complete.classList.add('hidden')
  }

  formatTime(seconds) {
    const total = Math.floor(seconds)
    const minutes = Math.floor(total / 60)
    const rest = total % 60
    return `${minutes}:${String(rest).padStart(2, '0')}`
  }

  updateMinimap(player, world, now) {
    if (now - this.lastMinimap < 80) return
    this.lastMinimap = now
    const ctx = this.minimapContext
    const size = this.el.minimap.width
    const extent = 128
    const toPx = value => (value / extent * 0.5 + 0.5) * size
    ctx.clearRect(0, 0, size, size)
    ctx.drawImage(world.minimap, 0, 0, size, size)

    const px = toPx(player.position.x)
    const pz = toPx(player.position.z)

    world.npcs.forEach(npc => {
      const x = toPx(npc.x)
      const z = toPx(npc.z)
      ctx.beginPath()
      ctx.arc(x, z, 6, 0, Math.PI * 2)
      ctx.fillStyle = '#6a84d8'
      ctx.fill()
      ctx.lineWidth = 2.5
      ctx.strokeStyle = '#fff8e8'
      ctx.stroke()
    })

    world.apples.forEach(apple => {
      if (apple.collected) return
      const x = toPx(apple.group.position.x)
      const z = toPx(apple.group.position.z)
      const pulse = 1 + Math.sin(now / 280 + apple.index) * 0.18
      ctx.beginPath()
      ctx.arc(x, z, 5.4 * pulse, 0, Math.PI * 2)
      ctx.fillStyle = '#ffc83d'
      ctx.fill()
      ctx.lineWidth = 2.2
      ctx.strokeStyle = '#6b3d10'
      ctx.stroke()
    })

    ctx.save()
    ctx.translate(px, pz)
    ctx.rotate(Math.PI - player.yaw)
    ctx.beginPath()
    ctx.moveTo(0, -13)
    ctx.lineTo(9, 10)
    ctx.lineTo(0, 5)
    ctx.lineTo(-9, 10)
    ctx.closePath()
    ctx.fillStyle = '#fffdf4'
    ctx.fill()
    ctx.lineWidth = 3
    ctx.strokeStyle = '#6b3e26'
    ctx.stroke()
    ctx.restore()

    ctx.beginPath()
    ctx.arc(px, pz, 16, 0, Math.PI * 2)
    ctx.strokeStyle = 'rgba(255, 244, 200, 0.55)'
    ctx.lineWidth = 2
    ctx.stroke()
  }
}

import * as THREE from 'three'
import { CONFIG } from './config.js'
import { createWorld } from './world.js'
import { createHorse } from './horse.js'
import { Player } from './player.js'
import { UI } from './ui.js'
import { AudioKit } from './audio.js'

const canvas = document.getElementById('scene')
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' })
const coarse = window.matchMedia('(pointer: coarse)').matches
renderer.setPixelRatio(Math.min(window.devicePixelRatio, coarse ? 1.6 : 1.8))
renderer.setSize(window.innerWidth, window.innerHeight)
renderer.shadowMap.enabled = true
renderer.shadowMap.type = THREE.PCFSoftShadowMap
renderer.outputColorSpace = THREE.SRGBColorSpace
renderer.toneMapping = THREE.ACESFilmicToneMapping
renderer.toneMappingExposure = 1.02

const scene = new THREE.Scene()
const camera = new THREE.PerspectiveCamera(54, window.innerWidth / window.innerHeight, 0.1, 720)

const state = {
  mode: 'loading',
  coat: 0,
  mane: 0,
  name: 'Comet',
  apples: 0,
  total: CONFIG.totalApples,
  questDone: false,
  lucky: false,
  elapsed: 0,
  muted: false
}

let world
let horse
let player
let ui
const audio = new AudioKit()
const keys = { forward: false, back: false, left: false, right: false, gallop: false, jump: false }
const joystick = { x: 0, y: 0 }
let touchGallop = false
let touchJump = false
let touchJumpTimer = 0
let elapsed = 0
let lastFrame = performance.now()
let menuTime = 0
let introTime = 0

const effectAdapter = {
  burst(position, color, count, options) {
    world.spawnParticles(position, color, count, options)
  }
}

function sanitizedName(value) {
  const clean = value.replace(/[^\p{L}\p{N} _'-]/gu, '').trim().slice(0, 12)
  return clean || 'Comet'
}

async function boot() {
  try {
    await Promise.race([
      document.fonts ? document.fonts.ready : Promise.resolve(),
      new Promise(resolve => setTimeout(resolve, 1400))
    ])
  } catch {
    // Fonts are cosmetic; continue with system fallbacks.
  }

  world = createWorld(scene)
  horse = createHorse(CONFIG.coats[state.coat], CONFIG.manes[state.mane])
  scene.add(horse.group)
  player = new Player(horse, world)

  ui = new UI({
    coats: CONFIG.coats,
    manes: CONFIG.manes,
    handlers: {
      onPlay: startGame,
      onCoat: index => {
        state.coat = index
        horse.setCoat(CONFIG.coats[index])
        audio.click()
      },
      onMane: index => {
        state.mane = index
        horse.setMane(CONFIG.manes[index].color)
        audio.click()
      },
      onName: value => {
        state.name = sanitizedName(value)
        ui.setName(state.name)
      },
      onPause: togglePause,
      onResume: resumeGame,
      onRestart: restartRide,
      onQuit: quitToTitle,
      onSound: toggleSound,
      onDialogClose: closeDialog,
      onContinue: continueExploring,
      onJoystick: (x, y) => {
        joystick.x = x
        joystick.y = y
      },
      onGallop: value => {
        touchGallop = value
      },
      onJump: () => {
        touchJump = true
        touchJumpTimer = 0.12
      }
    }
  })

  ui.setName(state.name)
  ui.setCoat(state.coat, false)
  ui.setMane(state.mane, false)
  ui.updateApples(0, state.total)

  positionMenuCamera(true)
  state.mode = 'menu'
  lastFrame = performance.now()
  requestAnimationFrame(frame)

  requestAnimationFrame(() => {
    window.setTimeout(() => ui.hideLoading(), 320)
  })
}

function startGame() {
  if (state.mode !== 'menu') return
  state.mode = 'playing'
  state.elapsed = 0
  introTime = 0
  audio.init()
  audio.click()
  player.cameraYaw = player.yaw + Math.PI
  player.cameraPitch = 0.27
  player.cameraInitialized = false
  ui.showGame()
  ui.setName(state.name)
  ui.updateStamina(player.stamina)
  ui.toast('Giddy up! Find all 12 Golden Apples.', 'star')
}

function togglePause() {
  if (state.mode === 'playing') {
    state.mode = 'paused'
    clearKeys()
    joystick.x = 0
    joystick.y = 0
    touchGallop = false
    audio.click()
    ui.hidePrompt()
    ui.showPause()
  } else if (state.mode === 'paused') {
    resumeGame()
  }
}

function resumeGame() {
  if (state.mode !== 'paused') return
  ui.hidePause()
  state.mode = 'playing'
  audio.click()
  player.cameraInitialized = false
}

function restartRide() {
  world.resetApples()
  state.apples = 0
  state.questDone = false
  state.lucky = false
  state.elapsed = 0
  horse.setLucky(false)
  player.reset()
  player.boost = 1
  ui.updateApples(0, state.total)
  ui.resetQuest()
  ui.hidePause()
  ui.hideComplete()
  ui.hideDialog()
  ui.hidePrompt()
  ui.updateStamina(player.stamina)
  clearKeys()
  joystick.x = 0
  joystick.y = 0
  touchGallop = false
  state.mode = 'playing'
  player.cameraInitialized = false
  audio.click()
  ui.toast('Fresh trail — 12 Golden Apples are waiting.', 'star')
}

function quitToTitle() {
  world.resetApples()
  state.apples = 0
  state.questDone = false
  state.lucky = false
  state.elapsed = 0
  horse.setLucky(false)
  player.reset()
  player.boost = 1
  ui.updateApples(0, state.total)
  ui.resetQuest()
  ui.hidePause()
  ui.hideComplete()
  ui.hideDialog()
  ui.hidePrompt()
  ui.updateStamina(player.stamina)
  ui.showTitle()
  clearKeys()
  joystick.x = 0
  joystick.y = 0
  touchGallop = false
  state.mode = 'menu'
  menuTime = 0
  positionMenuCamera(true)
  audio.click()
}

function toggleSound() {
  state.muted = !state.muted
  audio.setMuted(state.muted)
  ui.setMuted(state.muted)
  if (!state.muted) audio.click()
}

function clearKeys() {
  keys.forward = false
  keys.back = false
  keys.left = false
  keys.right = false
  keys.gallop = false
  keys.jump = false
}

function inputSnapshot() {
  let forward = (keys.forward ? 1 : 0) - (keys.back ? 1 : 0) + joystick.y
  let strafe = (keys.right ? 1 : 0) - (keys.left ? 1 : 0) + joystick.x
  const length = Math.hypot(forward, strafe)
  if (length > 1) {
    forward /= length
    strafe /= length
  }
  return {
    forward,
    strafe,
    gallop: keys.gallop || touchGallop,
    jump: keys.jump || touchJump,
    onJump: () => audio.jump(),
    onLand: () => audio.land(),
    onHoof: (speed, water) => audio.hoof(speed, water)
  }
}

function nearestNpc() {
  return state.mode === 'playing' ? player.nearNpc() : null
}

function interact() {
  if (state.mode !== 'playing') return
  const npc = nearestNpc()
  if (!npc) return
  state.mode = 'dialog'
  audio.click()
  clearKeys()
  touchGallop = false
  joystick.x = 0
  joystick.y = 0
  ui.hidePrompt()

  let text = ''
  let button = 'Let\'s ride!'
  if (npc.key === 'june') {
    if (state.questDone) {
      text = `The whole valley is talking about your ride, ${state.name}! That golden coat of yours is shining brighter than my lantern. Keep the lucky horseshoe — you earned every step of it.`
      button = 'Thanks, June!'
    } else if (state.apples === 0) {
      text = 'Well howdy, rider! The autumn wind scattered my twelve Golden Apples all over the valley. I spotted a few by the paddock, beneath the old oak, near the lakeside dock, and out by the windmill. Bring them all back and my lucky horseshoe is yours!'
      button = 'On it!'
    } else {
      const left = world.apples.filter(apple => !apple.collected).map(apple => apple.label)
      const hints = [...new Set(left)].slice(0, 4).join(', ')
      text = `You've found ${state.apples} of my twelve Golden Apples — splendid work! The rest should be around ${hints}. Follow the dirt trail and keep an eye out for that golden glow.`
      button = 'Will do!'
    }
  } else {
    if (state.questDone) {
      text = `Twelve out of twelve! June hasn't stopped smiling. If you want one more view, climb the east ridge at golden hour — the whole valley turns to honey from up there.`
      button = 'Nice tip!'
    } else {
      text = `Welcome to the valley, ${state.name}. I've been charting the trail all morning. My advice? Check the orchard east of the barn, the north shore of the lake, and the high meadow on the east ridge. Oh — and the old oak usually hides one in its roots.`
      button = 'Thanks, Milo!'
    }
  }

  ui.openDialog({
    name: npc.name,
    role: npc.role,
    initial: npc.name.split(' ').pop().charAt(0),
    text,
    button
  })
}

function closeDialog() {
  if (state.mode !== 'dialog') return
  ui.hideDialog()
  state.mode = 'playing'
  player.cameraInitialized = false
  audio.click()
}

function continueExploring() {
  if (state.mode !== 'complete') return
  ui.hideComplete()
  state.mode = 'playing'
  player.cameraInitialized = false
  audio.click()
}

function checkApples() {
  const px = player.position.x
  const pz = player.position.z
  const py = player.position.y + 1.45
  for (const apple of world.apples) {
    if (apple.collected) continue
    const distance = Math.hypot(px - apple.group.position.x, pz - apple.group.position.z)
    const vertical = Math.abs(py - apple.group.position.y)
    if (distance < 2.45 && vertical < 2.8) {
      if (world.collectApple(apple, effectAdapter, audio)) {
        state.apples += 1
        ui.updateApples(state.apples, state.total)
        ui.toast(`${apple.label} · ${state.apples} / ${state.total}`)
        if (state.apples >= state.total) finishQuest()
      }
      break
    }
  }
}

function finishQuest() {
  state.questDone = true
  state.lucky = true
  state.elapsed = Math.max(state.elapsed, 1)
  horse.setLucky(true)
  player.boost = 1.12
  audio.quest()
  ui.completeQuest()
  ui.hidePrompt()
  ui.toast('Lucky Horseshoe equipped · +12% gallop', 'star')
  for (let i = 0; i < 4; i += 1) {
    world.spawnParticles(
      new THREE.Vector3(player.position.x, player.position.y + 1.6 + i * 0.35, player.position.z),
      [0xffd166, 0xf78fb3, 0x9fd8ff, 0xfff4d8][i],
      26,
      { spread: 3.6, up: 5.4, size: 12, life: 1.5, gravity: 3.6 }
    )
  }
  state.mode = 'complete'
  window.setTimeout(() => {
    if (state.mode === 'complete') ui.showComplete({ time: ui.formatTime(state.elapsed) })
  }, 950)
}

function positionMenuCamera(immediate = false) {
  const target = new THREE.Vector3(
    player.position.x,
    player.position.y + 1.55,
    player.position.z
  )
  const angle = 0.66
  const radius = 7.1
  const desired = new THREE.Vector3(
    target.x + Math.sin(angle) * radius,
    target.y + 2.55,
    target.z + Math.cos(angle) * radius
  )
  if (immediate) {
    camera.position.copy(desired)
    player.cameraTarget.copy(target)
    camera.lookAt(target)
  }
  return { target, desired, angle, radius }
}

function updateMenuCamera(dt) {
  menuTime += dt
  const target = new THREE.Vector3(player.position.x, player.position.y + 1.5, player.position.z)
  const angle = 0.72 + Math.sin(menuTime * 0.12) * 0.28
  const radius = 7.1 + Math.sin(menuTime * 0.19) * 0.22
  const desired = new THREE.Vector3(
    target.x + Math.sin(angle) * radius,
    target.y + 2.45,
    target.z + Math.cos(angle) * radius
  )
  const ground = world.getHeight(desired.x, desired.z)
  desired.y = Math.max(desired.y, ground + 1.5)
  camera.position.lerp(desired, 1 - Math.exp(-dt * 2.5))
  camera.lookAt(target)
  horse.animate(dt, { speed: 0, grounded: true })
}

function handleKey(event, down) {
  const code = event.code
  let used = true
  switch (code) {
    case 'KeyW':
    case 'ArrowUp':
      keys.forward = down
      break
    case 'KeyS':
    case 'ArrowDown':
      keys.back = down
      break
    case 'KeyA':
    case 'ArrowLeft':
      keys.left = down
      break
    case 'KeyD':
    case 'ArrowRight':
      keys.right = down
      break
    case 'ShiftLeft':
    case 'ShiftRight':
      keys.gallop = down
      break
    case 'Space':
      keys.jump = down
      break
    case 'KeyE':
      if (down && !event.repeat) interact()
      used = false
      break
    case 'KeyM':
      if (down && !event.repeat) toggleSound()
      used = false
      break
    default:
      used = false
  }
  if (used) event.preventDefault()
}

window.addEventListener('keydown', event => handleKey(event, true))
window.addEventListener('keyup', event => handleKey(event, false))
window.addEventListener('blur', () => {
  clearKeys()
  touchGallop = false
  touchJump = false
})

let dragging = false
let lastPointerX = 0
let lastPointerY = 0

canvas.addEventListener('pointerdown', event => {
  if (state.mode !== 'playing') return
  dragging = true
  lastPointerX = event.clientX
  lastPointerY = event.clientY
  canvas.setPointerCapture?.(event.pointerId)
  event.preventDefault()
})
canvas.addEventListener('pointermove', event => {
  if (!dragging || state.mode !== 'playing') return
  const dx = event.clientX - lastPointerX
  const dy = event.clientY - lastPointerY
  lastPointerX = event.clientX
  lastPointerY = event.clientY
  player.cameraYaw -= dx * 0.006
  player.cameraPitch = THREE.MathUtils.clamp(player.cameraPitch + dy * 0.0045, 0.04, 1.15)
})
function endDrag() {
  dragging = false
}
canvas.addEventListener('pointerup', endDrag)
canvas.addEventListener('pointercancel', endDrag)
canvas.addEventListener('wheel', event => {
  if (state.mode !== 'playing') return
  event.preventDefault()
  player.cameraDistance = THREE.MathUtils.clamp(player.cameraDistance + event.deltaY * 0.006, 4.6, 14)
}, { passive: false })

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight
  camera.updateProjectionMatrix()
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, coarse ? 1.6 : 1.8))
  renderer.setSize(window.innerWidth, window.innerHeight)
})

document.addEventListener('visibilitychange', () => {
  if (document.hidden && state.mode === 'playing') togglePause()
})

function frame(now) {
  const dt = Math.min(0.05, Math.max(0, (now - lastFrame) / 1000))
  lastFrame = now
  elapsed += dt

  if (touchJump) {
    touchJumpTimer -= dt
    if (touchJumpTimer <= 0) touchJump = false
  }
  if (touchJump && !keys.jump) {
    // The jump is consumed by the player's latch; clear it shortly after.
  }

  world.update(dt, elapsed)
  audio.update(dt)

  if (state.mode === 'menu') {
    updateMenuCamera(dt)
  } else if (state.mode === 'playing') {
    state.elapsed += dt
    player.update(dt, inputSnapshot())
    player.updateCamera(camera, dt)
    checkApples()
    const npc = player.nearNpc()
    if (npc) ui.showPrompt(`Talk to ${npc.name}`)
    else ui.hidePrompt()
    ui.updateStamina(player.stamina)
    ui.updateMinimap(player, world, now)
  } else {
    horse.animate(dt, { speed: 0, grounded: true })
  }

  if (state.mode === 'dialog' || state.mode === 'paused' || state.mode === 'complete') {
    ui.hidePrompt()
    ui.updateMinimap(player, world, now)
  }

  renderer.render(scene, camera)
  requestAnimationFrame(frame)
}

