  dummy.rotation.set(0, 0, randRange(-0.03, 0.03))
  dummy.scale.set(1, 1, 1)
  dummy.updateMatrix()
  postMesh.setMatrixAt(index, dummy.matrix)
})
postMesh.castShadow = postMesh.receiveShadow = true
