    dummy.position.set((ax + bx) / 2, y + railY, (az + bz) / 2)
    dummy.rotation.set(0, -angle, 0)
    dummy.scale.set(1, 1, 1)
    dummy.updateMatrix()
    railMesh.setMatrixAt(railIndex, dummy.matrix)
    railIndex += 1
  }
})
